      "b3c": "<b>Danh mục màu</b> do bạn định nghĩa, được hiển thị trong mọi chế độ xem.",
      "b3d": "Mười ba giao diện, mười sáu ngôn ngữ và các phím tắt một phím.",
      "dl": "Tải xuống",
      "dlwin": "Tải xuống cho Windows",
      "gh": "Mã nguồn trên GitHub",
      "navTech": "Kỹ thuật",
      "navAbout": "Giới thiệu",
      "note": "Cài đặt hoặc chạy bản di động. Miễn phí, mã nguồn mở, GPLv3.<br>Không cần tài khoản, không thuê bao, không dịch vụ đồng bộ.<br>Không gửi dữ liệu đo từ xa và không có quảng cáo... mãi mãi.",
      "feats": "Ứng dụng làm được gì",
      "f1h": "Tháng, tuần, ngày, lịch biểu",
      "f1p": "Các cuộc hẹn trùng giờ được xếp cạnh nhau theo từng cột, nên cả hai cuộc hẹn trong cùng một giờ đều hiện rõ.\nCác mục cả ngày có một dải riêng phía trên lưới giờ. Chế độ xem tháng có thể thu phóng từ một đến sáu tuần và giữ các sự kiện kéo dài nhiều ngày liền mạch.",
      "f2h": "Danh mục màu",
      "f2p": "Tự tạo danh mục, đặt tên và chọn màu. Một cuộc hẹn có thể thuộc nhiều danh mục, và danh mục\nđầu tiên sẽ tô màu cho cuộc hẹn trong mọi chế độ xem. Khi đổi tên, mọi cuộc hẹn liên quan đều được cập nhật cùng lúc.",
      "f3h": "Bao nhiêu lịch tùy thích",
      "f3p": "Một lịch cho công việc, một lịch cho ca trực và một lịch cho gia đình. Mỗi lịch là một tệp riêng với mật khẩu riêng,\nhoặc không cần mật khẩu.<code>.kcal</code> tệp",
      "f4h": "Mã hóa tùy chọn",
      "f4p": "SQLCipher mã hóa dữ liệu khi lưu trữ: AES-256, HMAC-SHA512 trên từng trang và cơ chế dẫn xuất khóa riêng. Đây là tùy chọn bật, nên nếu không có\nmật khẩu, tệp vẫn là SQLite thuần.",
      "f5h": "Nhập và xuất iCalendar",
      "f5p": "Tính năng nhập và xuất được xây dựng theo RFC 5545 bằng trình phân tích riêng của Killendar. Các danh mục đi\ncùng cuộc hẹn theo cả hai chiều.<code>.ics</code> nhập / xuất",
      "f6h": "Mười ba giao diện, mười sáu ngôn ngữ",
      "f6p": "Có thể chuyển đổi mọi giao diện ngay khi ứng dụng đang chạy. Dark, Light, Black và 98SE đều có tám màu nhấn, tạo nên tổng cộng 41 diện mạo. Các phím tắt\nmột phím sẽ tự vô hiệu hóa khi bạn đang nhập vào một trường.",
      "f7h": "Bản di động hoặc bản cài đặt",
      "f7p": "Chạy từ USB, hoặc để ứng dụng tự cài đặt cho từng người dùng hay mọi người dùng trên máy.\nĐặt lịch cạnh tệp thực thi để có một bản hoàn toàn độc lập. Có chế độ cài đặt im lặng dành cho winget, Chocolatey và RMM.",
