      tk_34: "Aynı düğme parolayı değiştirir ya da kaldırıp dosyayı düz SQLite olarak geri yazar. Şifreli bir Killendar açılışta parolasını sorar; yanlış bir parola yalnızca sorunun yinelenmesine yol açar.",
