      tk_86: "Aynı anda yalnızca bir örnek çalışır. İkinci bir başlatma dosyasını zaten açık olan pencereye verip çıkar; uygulamanın iki kopyasını tek bir veritabanına yazar halde bırakmaz - ki bu SQLite'ı bozmanın en hızlı yoludur.",
      tk_87: "Bir <b>.kcal</b> dosyasına çift tıklamak onu veri klasörünüze kopyalar ve kopyayı açar, aslını olduğu yerde bırakır. Bir Killendar'a sürekli yazılır ve SQLite'ı bir ağ paylaşımı üzerinden kullanmak, bir veritabanını kaybetmenin iyi bilinen bir yoludur.",
      tk_88: "İmzalama",
      tk_89: "Yayımlanan sürümler Authenticode ile imzalanır. Hakkında kartı yayımcıyı, sertifika parmak izini ve çalışan exe'nin SHA-256'sını gösterir ve imzayı, gömülü sertifikayı okumakla yetinmeyip <b>WinVerifyTrust</b> ile doğrular - böylece kurcalanmış bir derleme, sahibi olmadığı bir imzalayıcıyı gösteremez. Zincir denetimi yalnızca önbellekten yapılır, bu yüzden Hakkında kartını açmak asla ağı beklemez.",
      tk_90: "Sözlük",
