      tk_92: "burada ne anlama gelir",
      tk_93: "Hem uygulamanın hem de tek bir takvim dosyasının adı. \"Başka bir Killendar aç\" demek, farklı bir <b>.kcal</b> dosyasına geçmek demektir.",
      tk_94: "Killendar'ın dosyası. Randevularınızı ve kategori tanımlarınızı tutan, şifreli ya da şifresiz bir SQLite veritabanı.",
      tk_95: "iCalendar, diğer bütün takvimlerin okuduğu değiş tokuş biçimi. Yalnızca içe ve dışa aktarma - Killendar asla bir .ics üzerinden çalışmaz.",
