      tk_45: "বিভাগগুলি স্ট্যান্ডার্ড <b>CATEGORIES</b> প্রপার্টি ব্যবহার করে দুদিকেই যায়, তাই অন্য কোনো ক্যালেন্ডার অ্যাপ ঘুরে এলেও টিকে থাকে। ইমপোর্ট করা যে বিভাগের সংজ্ঞা আপনি কখনও দেননি, সেটি বাদ পড়েও যায় না, চুপচাপ তৈরিও হয় না - নিরপেক্ষ ধূসর রঙে দেখায়। বিভাগ মুছে ফেলা মানে সেটি মুছেই থাকবে, আর ইমপোর্ট চুপিসারে তা ফিরিয়ে আনবে না।",
