      tk_47: "প্রায় সবকিছুই <b>একক কী</b>, কোনো মডিফায়ার নেই। এটি নিরাপদ থাকে কেবল একটি নিয়মের কারণে: টাইপ করার সময় খালি অক্ষরের শর্টকাট কখনও চলে না। ফোকাস কোনো টেক্সট ঘরে ঢোকামাত্র প্রতিটি এক-কী বাইন্ডিং সরে দাঁড়ায়, তাই শিরোনামে লেখা <b>w</b> স্রেফ একটি <b>w</b>, সপ্তাহ ভিউতে লাফ নয়। মডিফায়ারসহ কম্বিনেশন আগে যাচাই হয় আর সবসময়ই কাজ করে, কারণ টাইপিংয়ের সঙ্গে তাদের সংঘর্ষ হওয়ার উপায় নেই।",
