      tk_85: "আপনার অ্যাপয়েন্টমেন্ট যেমন আছে তেমনই রাখে, আর যোগ করা ফাইল অ্যাসোসিয়েশন সরিয়ে দেয়।",
      tk_86: "একসঙ্গে একটিই ইনস্ট্যান্স চলে। দ্বিতীয়বার চালালে সেটি নিজের ফাইলটি আগে থেকে খোলা উইন্ডোকে দিয়ে বেরিয়ে যায়, যাতে অ্যাপের দুটি কপি একই ডাটাবেসে লিখতে না থাকে - কারণ SQLite নষ্ট করার সবচেয়ে দ্রুত উপায় সেটাই।",
      tk_87: "কোনো <b>.kcal</b>-এ ডাবল-ক্লিক করলে সেটি আপনার ডেটা ফোল্ডারে কপি হয় আর কপিটিই খোলে, মূল ফাইল যেখানে ছিল সেখানেই থাকে। Killendar-এ অবিরাম লেখা চলে, আর নেটওয়ার্ক শেয়ারের উপর SQLite চালানো ডাটাবেস হারানোর সুপরিচিত উপায়।",
      tk_88: "স্বাক্ষর",
      tk_89: "রিলিজগুলি Authenticode দিয়ে স্বাক্ষরিত। সম্পর্কে কার্ড প্রকাশক, সার্টিফিকেটের থাম্বপ্রিন্ট আর চলন্ত exe-র SHA-256 দেখায়, আর ভেতরে বসানো সার্টিফিকেট শুধু না পড়ে <b>WinVerifyTrust</b> দিয়ে স্বাক্ষর যাচাই করে - তাই কারচুপি করা বিল্ড এমন কোনো স্বাক্ষরকারীর নাম দেখাতে পারে না যা তার নিজের নয়। চেইন যাচাই শুধু ক্যাশ থেকেই হয়, তাই সম্পর্কে কার্ড খুললে নেটওয়ার্কের অপেক্ষায় কখনও আটকে থাকে না।",
