      tk_92: "এখানে যা বোঝায়",
      tk_93: "অ্যাপটিও, আবার একটি ক্যালেন্ডার ফাইলও। “অন্য একটি Killendar খুলুন” মানে অন্য একটি <b>.kcal</b>-এ যান।",
      tk_94: "Killendar-এর ফাইল। একটি SQLite ডাটাবেস, যাতে থাকে আপনার অ্যাপয়েন্টমেন্ট আর বিভাগের সংজ্ঞা - এনক্রিপ্ট করা হোক বা না হোক।",
      tk_95: "iCalendar - অন্য সব ক্যালেন্ডার যে আদান-প্রদানের ফরম্যাট পড়ে। শুধু ইমপোর্ট ও এক্সপোর্ট - Killendar কখনও এটি থেকে চলে না।",
      tk_96: "বিভাগ",
