      tk_3: "Файл",
      tk_4: "Бір <b>.kcal</b> файлы - бір Killendar. Бұл орнында ашылып, орнында жазылатын кәдімгі SQLite\nдерекқоры, сондықтан қолданбаға кірмей-ақ оны кез келген SQLite құралымен оқи аласыз. Меншікті\nконтейнер де, қайта құратын индекс те жоқ.",
      tk_5: "файл",
      tk_6: "ол не үшін керек",
