      tk_9: "Killendar файлдары әдепкіде <b>%APPDATA%\\Killendar</b> ішінде жатады. Killendar файлдарын басқару каталогты\nжазуға болатын кез келген жергілікті қалтаға ауыстыра алады немесе өзін-өзі қамтитын портативті көшірме үшін оны\n<b>Killendar.exe</b> қасына қоя алады. Бүкіл машинаға орнату әлі де әр Windows тіркелгісіне бөлек профиль қалтасын береді.",
