      tk_13: "<b>meta</b> - схема нұсқасы және файлды жасаған қолданба нұсқасы, жылдар өткен соң\nқолға түскен файлды сараптау үшін.",
      tk_14: "Уақыт",
      tk_15: "Уақыты бар кездесулер UTC-де сақталып, шеттерінде түрлендіріледі, сондықтан басқа уақыт белдеуіне\nапарылған күнтізбе бәрібір дұрысын айтады.",
      tk_16: "Күні бойы жазбалары - әдейі жасалған ерекшелік: олар <b>Z</b> әрпінсіз, түрлендірілмей сақталатын\nқалқымалы күнтізбелік күндер. Оларды UTC-ге түрлендіру UTC-ден шығысқа қарай тұрған әркім үшін күні бойы\nкездесуін алдыңғы күнге жылжытар еді.",
