      tk_41: "<b>settings.json</b> қарапайым мәтін күйінде қалады. Онда тақырып, локаль, терезе орны және қай\nKillendar белсенді екені сақталады.",
      tk_42: "<b>.ics</b> экспорты анықтамасы бойынша қарапайым мәтін. Шифрланған Killendar-дан экспорттау\nшифрланбаған көшірме жазады, ал қолданба сізді кейін емес, экспорт сәтінде ескертеді.",
      tk_43: "iCalendar",
      tk_44: "Импорт пен экспорт Killendar-дың өз талдағышымен тікелей RFC 5545 бойынша жазылған; уақыт белдеулерінің атауларын ғана TimeZoneConverter кітапханасы анықтайды.\nИмпорт күнтізбеде бұрыннан бар кездесулерді өткізіп жібереді және қаншасы қосылып, қаншасы\nөткізілгенін хабарлайды.",
      tk_45: "Санаттар стандартты <b>CATEGORIES</b> сипаты арқылы екі бағытта да жүреді, сондықтан олар\nбасқа күнтізбе қолданбасы арқылы өткен сапардан аман шығады. Импорттаған, бірақ ешқашан белгілемеген санатыңыз\nтасталмай да, үнсіз жасалмай да, бейтарап сұр түспен көрсетіледі: санатты жою күшінде\nқалуға тиіс, ал импорт оны үнсіз кері қайтармауы керек.",
      tk_46: "Пернетақта",
      tk_47: "Барлығы дерлік - модификаторсыз <b>жалғыз перне</b>. Бұл бір ғана ереженің арқасында қауіпсіз:\nжалаң әріпті тіркесім сіз теріп отырғанда ешқашан іске қосылмайды. Фокус мәтін өрісіне түскен сәтте\nбарлық жалғыз пернелік байланыс әрекет етпейді, сондықтан атаудағы <b>w</b> - бұл <b>w</b>, апта көрінісіне\nөту емес. Модификаторы бар тіркесімдер бірінші тексеріледі және әрқашан жұмыс істейді, өйткені олар\nтеруге кедергі жасай алмайды.",
