      tk_74: "<b>Тінтуір:</b> Ай көрінісінің үстінде Ctrl+дөңгелек көрінетін ауқымды бір аптадан алты аптаға дейін өзгертеді,\nбос емес күндерге тігінен көбірек орын береді. Апта немесе Күн үстінде Ctrl+дөңгелек уақыт торының тығыздығын өзгертеді.",
