      tk_87: "<b>.kcal</b> файлын екі рет басу оны деректер қалтаңызға көшіріп, көшірмесін ашады, ал\nтүпнұсқасы тұрған жерінде қалады. Killendar файлына үнемі жазу жүреді, ал желілік ресурстағы SQLite -\nдерекқорды жоғалтудың белгілі жолы.",
      tk_88: "Қол қою",
      tk_89: "Шығарылымдарға Authenticode қолтаңбасы қойылған. Бағдарлама туралы карточкасы жариялаушыны, сертификат\nсаусақ ізін және іске қосылған exe файлының SHA-256 мәнін көрсетеді, әрі ол қолтаңбаны ендірілген сертификатты жай\nоқып қана қоймай, <b>WinVerifyTrust</b> арқылы тексереді - сондықтан бұрмаланған құрастырма өзіне тиесілі емес\nқол қоюшыны көрсете алмайды. Тізбек тексерісі тек кештен алынады, сондықтан бағдарлама туралы карточкасын ашу желіні күтіп\nешқашан тұрып қалмайды.",
