      tk_92: "бұл жерде нені білдіреді",
      tk_93: "Әрі қолданбаның өзі, әрі бір күнтізбе файлы. \"Басқа Killendar ашу\" дегеніміз\nбасқа <b>.kcal</b> файлына ауысу.",
      tk_94: "Killendar файлы. Кездесулеріңіз бен санат анықтамаларыңызды сақтайтын, шифрланған\nнемесе шифрланбаған SQLite дерекқоры.",
      tk_95: "iCalendar, басқа күнтізбенің бәрі оқитын алмасу пішімі. Тек импорт пен\nэкспорт - Killendar одан ешқашан жұмыс істемейді.",
      tk_96: "Санат",
      tk_97: "Өзіңіз белгілейтін атауы бар түс. Бір кездесуде бірнешеуі бола алады; түсті\nбіріншісі береді. Анықтамалар файлда тұрады, сондықтан онымен бірге жүреді.",
      tk_98: "Иесіз санат",
