      tk_100: "Күні бойы",
      tk_101: "Уақыты жоқ, қалқымалы күн ретінде сақталатын кездесу. Ол уақыт белдеуімен\nешқашан жылжымайды.",
      tk_102: "Қалқымалы күн",
