 "dl": "Завантажити",
 "dlwin": "Завантажити для Windows",
 "gh": "Вихідний код на GitHub",
 "navTech": "Технічне",
 "navAbout": "Про програму",
 "note": "Установіть або запустіть портативно. Безкоштовно, відкритий вихідний код, GPLv3.<br>Без облікового запису, без підписки, без служби синхронізації.<br>Жодної телеметрії і жодної реклами... ніколи.",
 "feats": "Що він уміє",
 "f1h": "Місяць, тиждень, день, розклад",
 "f1p": "Зустрічі, що перетинаються, розкладаються поруч по доріжках, тому година з подвійним записом показує обидві.\nЗаписи на весь день отримують власну смугу над годинною сіткою. Подання місяця масштабується від одного до шести тижнів і не розриває багатоденні зустрічі.",
 "f2h": "Кольорові категорії",
 "f2p": "Задайте свої, дайте їм назви та виберіть кольори. Зустріч може мати кілька категорій, і\nперша розфарбовує її в кожному поданні. Перейменування оновлює всі зустрічі одразу.",
 "f3h": "Скільки завгодно календарів",
 "f3p": "Один для роботи, один для чергувань, один для сім'ї. Кожен - окремий файл зі своїм\nпаролем або взагалі без нього.<code>.kcal</code> файли",
 "f4h": "Шифрування за бажанням",
