 "f5h": "iCalendar на вході й на виході",
 "f5p": "Імпорт та експорт написано прямо за RFC 5545 власним парсером Killendar. Категорії мандрують\nразом із зустріччю в обидва боки.<code>.ics</code> імпорт / експорт",
 "f6h": "Тринадцять тем, 16 мов",
 "f6p": "Будь-яку тему можна змінити на ходу. Темна, Світла, Чорна та 98SE беруть по вісім відтінків акценту, тож загалом виходить 41 вигляд. Комбінації\nз однієї клавіші, які відступають, поки ви друкуєте в полі.",
 "f7h": "Портативно або з установленням",
 "f7p": "Запускайте його з USB-флешки або дайте йому встановитися для вас одного чи для всіх на машині.\nТримайте календар поруч із виконуваним файлом заради самодостатньої копії. Є шлях тихого встановлення для winget, Chocolatey та RMM.",
 "f8h": "Підписано й можна перевірити",
 "f8p": "Картка про програму показує видавця, відбиток сертифіката та SHA-256 запущеного exe,\nперевірений через WinVerifyTrust, а не просто зчитаний із файлу.",
 "foot": "<a href=\"https://github.com/SteveTheKiller/Killendar\" target=\"_blank\" rel=\"noopener\">Вихідний код на GitHub</a> &middot; GPLv3 &middot; Частина <a href=\"https://killertools.net\" target=\"_blank\" rel=\"noopener\">killertools.net</a>",
 "about_kicker": "Про програму",
 "about_sub": "Історія календаря й виїзного техніка, який його написав.",
 "maker_h": "Автор",
 "maker_q": "\"Усе почалося як жарт. Я не міг придумати вбивчу функцію, заради якої варто було б це випускати. Потім до мене дійшло, що легкість і небажання будь-що від вас отримувати - це і є та сама функція.\"",
 "maker_p1": "Я <b>Steve the Killer</b>. Шість років full-stack розробником, вісім років виїзним техніком у кількох компаніях, а тепер я працюю у внутрішній команді ШІ-інженерії в MSP, тож написати потрібний мені інструмент для мене так само природно, як полагодити машину, що стоїть переді мною.",
 "maker_p2": "Killendar якийсь час лежав у мене на диску як річ, зроблена для себе. Кожен календар, яким я міг би замість нього користуватися, вимагав обліковий запис, а мені не хотілося віддавати логін тому, чия єдина робота - пам'ятати, що стоматолог у четвер. Тож у застосунку без вбивчої функції вона все-таки знайшлася: він нічого від вас не хоче.",
 "app_h": "Застосунок",
 "app_p1": "<b>Killendar</b> - це нативний календар для Windows, що постачається одним самодостатнім виконуваним файлом. Установіть його або запустіть портативно. Немає служби, де треба реєструватися, немає облікового запису й немає підписки. Передайте комусь .exe, і в нього є календар.",
 "app_p2": "Ваші зустрічі живуть в одному файлі <b>.kcal</b> у вашому власному профілі. Це звичайна база даних SQLite, тож вона ваша: читайте її, робіть резервні копії, переносьте чи відкривайте будь-яким інструментом SQLite. Задайте пароль, і весь файл буде зашифровано на диску за допомогою SQLCipher; не задавайте - і він залишиться звичайним SQLite. У будь-якому разі нічого не залишає машину, бо йти йому нікуди.",
 "app_p3": "Він уміє подання місяця, тижня, дня та розкладу, кольорові категорії, які ви задаєте самі, й імпорт та експорт iCalendar, щоб усе, що ви в нього поклали, могло вийти назад. Тринадцять тем, 16 мов і комбінація клавіш для всього, бо інструмент, який доводиться шукати мишею, забирає той самий час, який мав заощадити.",
 "app_p4": "Багато з того, що з'явиться далі, визначать прохання людей. Сторінка <a href=\"https://github.com/SteveTheKiller/Killendar/issues\" target=\"_blank\" rel=\"noopener\">GitHub issues</a> відкрита для всіх, і пропозиції справді визначають, куди все піде. Killendar - вільне програмне забезпечення під ліцензією <b>GPL-3.0</b>, а на сторінці <a href=\"technical.html\">Технічне</a> лежать подробиці.",
 "contact_h": "Контакти &amp; посилання",
 "contact_p": "Знайдіть мене, заведіть баг або просто привітайтеся:",
 "also_h": "Спробуйте також...",
 "also_kp": "PDF-редактор з відкритим вихідним кодом для Windows",
