 "also_kb": "Інструмент діагностики та ремонту з відкритим кодом для Windows",
 "also_kst": "Зашифрований альбом знімків екрана з відкритим кодом для Windows",
 "also_kn": "Нотатник з відкритим вихідним кодом для Windows",
 "also_ksh": "Файловий менеджер, термінал і редактор в одному exe",
 "tk_1": "Технічне",
 "tk_2": "Що являє собою файл, де він лежить і що насправді покриває шифрування.",
 "tk_3": "Файл",
 "tk_4": "Один файл <b>.kcal</b> - це один Killendar. Це звичайна база даних SQLite, яка відкривається й пишеться\nна місці, тож ви можете читати її будь-яким інструментом SQLite, не заходячи в застосунок. Жодного\nвласного контейнера і жодного індексу, який треба перебудовувати.",
 "tk_5": "файл",
 "tk_6": "для чого він потрібен",
 "tk_7": "Killendar. Жива база даних, що пишеться на місці.",
 "tk_8": "Лише для обміну. Імпорт та експорт.",
 "tk_9": "Файли Killendar за замовчуванням лежать у <b>%APPDATA%\\Killendar</b>. Керування файлами Killendar може перевести каталог до\nбудь-якої доступної для запису локальної теки або покласти його поруч із <b>Killendar.exe</b> заради самодостатньої\nпортативної копії. Установлення для всієї машини, як і раніше, за замовчуванням дає окрему теку профілю кожному обліковому запису Windows.",
 "tk_10": "Що в нього всередині",
