 "tk_13": "<b>meta</b> - версія схеми та версія застосунку, що створив файл, для розбору\nфайла, який спливе через роки.",
 "tk_14": "Час",
 "tk_15": "Зустрічі з часом зберігаються в UTC і перетворюються на межах, тому календар, відвезений в\nінший часовий пояс, усе одно каже правильні речі.",
 "tk_16": "Записи на весь день - виняток, і навмисно: це плаваючі календарні дати,\nщо зберігаються без перетворення й без <b>Z</b>. Переведення їх в UTC зсунуло б зустріч на весь день\nна попередній день для всіх, хто східніше за UTC.",
