 "tk_22": "Шифрування",
 "tk_23": "Шифрування вмикається за бажанням. Без пароля файл - звичайний SQLite. Задайте пароль кнопкою замка\nв заголовку вікна, і весь файл буде зашифровано на диску за допомогою SQLCipher.",
 "tk_24": "властивість",
 "tk_25": "значення",
