  "kdm_step_1": "<strong>Tải và chạy KillerMCP Setup.</strong> Dùng trình cài đặt đã ký ở trên.",
  "kdm_step_2": "<strong>Để trình cài đặt kết nối tác tử.</strong> Nó cài môi trường chạy dùng chung và đăng ký KillerMCP với Codex, Claude Code, Claude Desktop, Cursor, GitHub Copilot, Gemini CLI và Windsurf nếu tìm thấy.",
  "kdm_step_3": "<strong>Mở cuộc trò chuyện mới với tác tử và hỏi.</strong> KillerMCP phát hiện Killendar trên máy tính của bạn và cung cấp các công cụ lịch qua cùng một kết nối.",
  "kdm_examples_intro": "<code>killer</code> là dạng ngắn nhất. Tác tử sẽ nhận ra Killendar khi yêu cầu rõ ràng là về lịch của bạn. Dùng <code>killendar</code> khi bạn muốn gọi đích danh ứng dụng.",
  "kdm_ex_1": "killer hôm nay lịch của tôi có gì",
  "kdm_ex_2": "killer hiện các cuộc hẹn tuần này của tôi",
  "kdm_ex_3": "killendar thứ Sáu tới có lịch gì",
  "kdm_ex_4": "killer liệt kê 20 sự kiện sắp tới của tôi",
  "kdm_ex_5": "killer thêm một buổi đi hiện trường ngày 15 tháng 10 từ 9 đến 10 giờ sáng",
  "kdm_ex_6": "killendar thêm kỳ nghỉ cả ngày vào ngày 15 tháng 10",
  "kdm_tools_intro": "KillerMCP đọc lịch đang dùng, kể cả sự kiện lặp lại, và tạo từng cuộc hẹn qua ứng dụng đang chạy.",
  "kdm_tool_1_t": "Đọc lịch trình",
  "kdm_tool_1_b": "Xem sự kiện trong tối đa 31 ngày mà không cần mở cửa sổ lịch.",
  "kdm_tool_2_t": "Hiểu lịch lặp lại",
  "kdm_tool_2_b": "Các cuộc hẹn lặp lại được triển khai thành các ngày trong khoảng thời gian được yêu cầu.",
  "kdm_tool_3_t": "Tạo cuộc hẹn",
  "kdm_tool_3_b": "Thêm cuộc hẹn có giờ hoặc cả ngày khi Killendar đang mở và đã mở khóa.",
  "kdm_tool_4_t": "Chỉnh sửa vẫn trong ứng dụng",
  "kdm_tool_4_b": "Việc sửa, xóa và thiết lập cuộc hẹn lặp lại vẫn diễn ra trong Killendar.",
  "kdm_priv_1": "Tra cứu lịch trình đọc tệp cục bộ mà không thay đổi nó. Việc tạo đi qua ứng dụng Killendar đang mở, nên lịch được cập nhật ngay. Ứng dụng khách MCP và nhà cung cấp mô hình có thể nhận chi tiết cuộc hẹn được gửi tới và trả về từ các công cụ này.",
  "kdm_arch_1": "KillerMCP kết nối trợ lý AI của bạn với các ứng dụng Killer được hỗ trợ đã cài trên máy. Nó tìm Killendar và cung cấp công cụ lịch trình cho các truy vấn chỉ đọc có giới hạn. Công cụ tạo gửi một cuộc hẹn đã xác thực tới ứng dụng đang chạy và đã mở khóa, ứng dụng sẽ lưu và làm mới lịch. Các lệnh chạy trên máy tính của bạn, không phải trên trang web này.",
  "kdm_limit_1": "Một yêu cầu lịch trình có thể bao quát tối đa 31 ngày và trả về tối đa 100 sự kiện.",
  "kdm_limit_2": "Tra cứu lịch trình không thể mở khóa Killendar được bảo vệ bằng mật khẩu.",
  "kdm_limit_3": "Để tạo cuộc hẹn, Killendar phải đang mở và đã mở khóa.",
  "kdm_limit_4": "Việc sửa, xóa và tạo cuộc hẹn lặp lại vẫn cần giao diện ứng dụng.",
  "kdm_conn_title": "Một kết nối cho cả gia đình ứng dụng",
  "kdm_conn_1": "Cài KillerMCP một lần. Nó phát hiện các ứng dụng Killer được hỗ trợ trên máy và thêm công cụ của chúng vào một kết nối tác tử. Khi có thêm tích hợp mới, cùng môi trường chạy KillerMCP có thể cung cấp chúng mà không cần trình cài đặt riêng cho từng ứng dụng.",
  "mcp_nav_conn": "Một kết nối",
  "kd_shot_1": "Chế độ xem tháng, giao diện Delirium: trọn tháng Mười, sự kiện cả ngày chạy ngang phía trên mỗi ngày",
  "kd_shot_2": "Chế độ xem tuần, giao diện Decay: tuần làm việc năm ngày, thanh công cụ có biểu tượng nhỏ và nhãn bên cạnh",
  "kd_shot_3": "Chế độ xem ngày, giao diện 98SE: sửa một cuộc hẹn trong thanh bên cạnh lưới giờ",
  "kd_shot_4": "Chế độ xem lịch trình, giao diện Blood: những ngày sắp tới dạng danh sách, nhãn dưới biểu tượng, Film Grain tắt",
  "kd_shot_5": "Các tuần liên tiếp, giao diện Ectoplasm: ba tuần tính từ tuần hiện tại ở mức thu phóng 110%",
  "kd_shot_6": "Phím tắt, giao diện Black với màu nhấn xanh ngọc: lớp phủ F1 với mọi phím trên một bàn phím vẽ sẵn",
  "kd_shot_7": "Thẻ Giới thiệu, giao diện Sepulchre: phiên bản, chữ ký và chi tiết bản dựng ở mức thu phóng 120%, thanh công cụ chỉ có chữ",
