  "kdm_hero": "Kérdezzen a naptáráról, vagy vegyen fel egy találkozót.",
  "kdm_intro": "A KillerMCP egyetlen helyi kapcsolatban tartalmazza mind a 81 KillerTools segédprogramot és a támogatott Killer-alkalmazások eszközeit. Nincs szükség külön Killendar-telepítőre, forráskódra, Node-ra vagy parancslistára.",
  "kdm_step_1": "<strong>Töltse le és futtassa a KillerMCP Setupot.</strong> Használja a fenti aláírt telepítőt.",
  "kdm_step_2": "<strong>Hagyja, hogy a telepítő csatlakoztassa az ügynököt.</strong> Telepíti a közös futtatókörnyezetet, és regisztrálja a KillerMCP-t a Codexben, a Claude Code-ban, a Claude Desktopban, a Cursorban, a GitHub Copilotban, a Gemini CLI-ben és a Windsurfben, ha megtalálja őket.",
  "kdm_step_3": "<strong>Nyisson új csevegést az ügynökkel, és kérdezzen.</strong> A KillerMCP felismeri a Killendart a számítógépén, és ugyanazon a kapcsolaton elérhetővé teszi a naptáreszközeit.",
  "kdm_examples_intro": "A <code>killer</code> a legrövidebb forma. Az ügynök felismeri a Killendart, ha a kérés egyértelműen a naptárára vonatkozik. Használja a <code>killendar</code> szót, ha kifejezetten meg akarja nevezni az alkalmazást.",
  "kdm_ex_1": "killer mi van ma a naptáramban",
