  "kdm_ex_6": "killendar vegyél fel egész napos szabadságot október 15-re",
  "kdm_tools_intro": "A KillerMCP beolvassa az aktív naptárat az ismétlődő eseményekkel együtt, és a futó alkalmazáson keresztül egyedi találkozókat hoz létre.",
  "kdm_tool_1_t": "A napirend olvasása",
  "kdm_tool_1_b": "Akár 31 nap eseményeinek megtekintése a naptárablak megnyitása nélkül.",
  "kdm_tool_2_t": "Az ismétlődés megértése",
  "kdm_tool_2_b": "Az ismétlődő találkozók a kért időszakon belüli dátumokra bomlanak.",
  "kdm_tool_3_t": "Találkozók létrehozása",
  "kdm_tool_3_b": "Időponthoz kötött vagy egész napos találkozó felvétele, amíg a Killendar nyitva van és fel van oldva.",
  "kdm_tool_4_t": "A szerkesztés az alkalmazásban marad",
  "kdm_tool_4_b": "A szerkesztés, a törlés és az ismétlődő találkozók beállítása továbbra is a Killendarban történik.",
  "kdm_priv_1": "A napirend lekérdezése módosítás nélkül olvassa a helyi fájlt. A létrehozás a megnyitott Killendar alkalmazáson keresztül történik, így a naptár azonnal frissül. Az MCP-kliens és a modell szolgáltatója megkaphatja az ezeknek az eszközöknek küldött és tőlük visszakapott találkozóadatokat.",
  "kdm_arch_1": "A KillerMCP összekapcsolja az MI-asszisztensét a számítógépén telepített, támogatott Killer-alkalmazásokkal. Megtalálja a Killendart, és napirendeszközt kínál korlátozott, csak olvasható lekérdezésekhez. A létrehozó eszköz ellenőrzött találkozót küld a futó, feloldott alkalmazásnak, amely elmenti azt, és frissíti a naptárat. A parancsok az Ön számítógépén futnak, nem ezen a weboldalon.",
  "kdm_limit_1": "Egy napirendkérés legfeljebb 31 napot fedhet le, és legfeljebb 100 eseményt adhat vissza.",
  "kdm_limit_2": "A napirend lekérdezése nem tudja feloldani a jelszóval védett Killendarokat.",
  "kdm_limit_3": "Találkozó létrehozásához a Killendarnak nyitva és feloldva kell lennie.",
  "kdm_limit_4": "A szerkesztéshez, a törléshez és az ismétlődő találkozók létrehozásához továbbra is az alkalmazás felülete kell.",
  "kdm_conn_title": "Egy kapcsolat az egész családnak",
  "kdm_conn_1": "Telepítse egyszer a KillerMCP-t. Felismeri a számítógépén lévő támogatott Killer-alkalmazásokat, és eszközeiket egyetlen ügynökkapcsolathoz adja. Ahogy újabb integrációk jelennek meg, ugyanaz a KillerMCP futtatókörnyezet biztosítja őket, minden alkalmazáshoz külön telepítő nélkül.",
  "mcp_nav_conn": "Egy kapcsolat",
  "kd_shot_1": "Havi nézet, Delirium téma: egy teljes október, az egész napos események minden nap tetején húzódnak",
