  "kdm_hero": "Consulta tu calendario o añade una cita.",
  "kdm_intro": "KillerMCP incluye las 81 utilidades de KillerTools y las herramientas de las apps Killer compatibles en una sola conexión local. No necesitas un instalador aparte para Killendar, ni el código fuente, ni Node, ni una lista de comandos.",
