  "kdm_step_2": "<strong>Deja que el instalador conecte tu agente.</strong> Instala el entorno de ejecución compartido y registra KillerMCP en Codex, Claude Code, Claude Desktop, Cursor, GitHub Copilot, Gemini CLI y Windsurf cuando los encuentra.",
