  "kdm_tool_4_b": "Editar, eliminar y configurar citas periódicas se sigue haciendo en Killendar.",
  "kdm_priv_1": "La consulta de la agenda lee el archivo local sin modificarlo. La creación pasa por la app Killendar abierta, así que su calendario se actualiza al instante. Tu cliente MCP y su proveedor de modelo pueden recibir los detalles de las citas enviados a estas herramientas y devueltos por ellas.",
  "kdm_arch_1": "KillerMCP conecta tu asistente de IA con las apps Killer compatibles instaladas en tu equipo. Encuentra Killendar y ofrece una herramienta de agenda para consultas limitadas de solo lectura. La herramienta de creación envía una cita validada a la app en ejecución y desbloqueada, que la guarda y actualiza el calendario. Los comandos se ejecutan en tu equipo, no en esta página web.",
  "kdm_limit_1": "Una consulta de agenda puede abarcar hasta 31 días y devolver hasta 100 eventos.",
  "kdm_limit_2": "La consulta de la agenda no puede desbloquear un Killendar protegido con contraseña.",
  "kdm_limit_3": "Para crear una cita, Killendar debe estar abierto y desbloqueado.",
  "kdm_limit_4": "Editar, eliminar y crear citas periódicas sigue requiriendo la interfaz de la app.",
  "kdm_conn_title": "Una conexión para toda la familia",
  "kdm_conn_1": "Instala KillerMCP una vez. Detecta las apps Killer compatibles de tu equipo y añade sus herramientas a una sola conexión del agente. A medida que salgan nuevas integraciones, el mismo entorno de KillerMCP podrá ofrecerlas sin un instalador aparte para cada app.",
  "mcp_nav_conn": "Una conexión",
  "kd_shot_1": "Vista de mes, tema Delirium: un octubre completo, los eventos de todo el día recorren la parte superior de cada día",
  "kd_shot_2": "Vista de semana, tema Decay: una semana laboral de cinco días, barra de herramientas con iconos pequeños y etiquetas al lado",
  "kd_shot_3": "Vista de día, tema 98SE: edición de una cita en el panel lateral junto a la cuadrícula de horas",
  "kd_shot_4": "Vista de agenda, tema Blood: los próximos días como lista, etiquetas bajo los iconos, Film Grain desactivado",
  "kd_shot_5": "Semanas continuas, tema Ectoplasm: tres semanas desde la actual con un zoom del 110 %",
  "kd_shot_6": "Atajos de teclado, tema Black con el acento turquesa: la superposición de F1 con cada atajo sobre un teclado dibujado",
  "kd_shot_7": "Tarjeta Acerca de, tema Sepulchre: versión, firma y detalles de compilación con un zoom del 120 %, barra de herramientas solo con texto",
