  "contact_src_card": "Code source sur GitHub<span class=\"sub\">github.com/<wbr>SteveTheKiller</span>",
  "contact_issue_card": "Signaler un problème<span class=\"sub\">tickets GitHub</span>",
  "kdm_hero": "Interrogez votre calendrier ou ajoutez un rendez-vous.",
  "kdm_intro": "KillerMCP réunit les 81 utilitaires KillerTools et les outils des apps Killer prises en charge dans une seule connexion locale. Vous n'avez besoin ni d'un installateur Killendar séparé, ni du code source, ni de Node, ni d'une liste de commandes.",
  "kdm_step_1": "<strong>Téléchargez et lancez KillerMCP Setup.</strong> Utilisez l'installateur signé ci-dessus.",
  "kdm_step_2": "<strong>Laissez l'installateur connecter votre agent.</strong> Il installe le moteur partagé et enregistre KillerMCP auprès de Codex, Claude Code, Claude Desktop, Cursor, GitHub Copilot, Gemini CLI et Windsurf lorsqu'ils sont présents.",
  "kdm_step_3": "<strong>Ouvrez une nouvelle conversation avec l'agent et posez votre question.</strong> KillerMCP détecte Killendar sur votre ordinateur et rend ses outils de calendrier disponibles par la même connexion.",
  "kdm_examples_intro": "<code>killer</code> est la forme la plus courte. Votre agent reconnaît Killendar quand la demande porte clairement sur votre calendrier. Utilisez <code>killendar</code> quand vous voulez nommer l'application.",
  "kdm_ex_1": "killer qu'est-ce que j'ai dans mon calendrier aujourd'hui",
  "kdm_ex_2": "killer montre mes rendez-vous de cette semaine",
  "kdm_ex_3": "killendar qu'est-ce qui est prévu vendredi prochain",
  "kdm_ex_4": "killer liste mes 20 prochains événements",
  "kdm_ex_5": "killer ajoute une visite sur site le 15 octobre de 9 h à 10 h",
  "kdm_ex_6": "killendar ajoute des vacances sur toute la journée le 15 octobre",
  "kdm_tools_intro": "KillerMCP lit le calendrier actif, y compris les événements récurrents, et crée des rendez-vous uniques via l'app en cours d'exécution.",
  "kdm_tool_1_t": "Lire votre agenda",
  "kdm_tool_1_b": "Voir jusqu'à 31 jours d'événements sans ouvrir la fenêtre du calendrier.",
  "kdm_tool_2_t": "Comprendre la récurrence",
  "kdm_tool_2_b": "Les rendez-vous récurrents sont développés en dates dans la période demandée.",
  "kdm_tool_3_t": "Créer des rendez-vous",
  "kdm_tool_3_b": "Ajouter un rendez-vous avec horaire ou sur toute la journée pendant que Killendar est ouvert et déverrouillé.",
  "kdm_tool_4_t": "Les modifications restent dans l'app",
  "kdm_tool_4_b": "La modification, la suppression et la création de rendez-vous récurrents se font toujours dans Killendar.",
  "kdm_priv_1": "La consultation de l'agenda lit le fichier local sans le modifier. La création passe par l'app Killendar ouverte, son calendrier se met donc à jour immédiatement. Votre client MCP et son fournisseur de modèle peuvent recevoir les détails des rendez-vous envoyés à ces outils et renvoyés par eux.",
  "kdm_arch_1": "KillerMCP relie votre assistant IA aux apps Killer prises en charge installées sur votre ordinateur. Il trouve Killendar et propose un outil d'agenda pour des requêtes limitées en lecture seule. L'outil de création envoie un rendez-vous validé à l'app en cours d'exécution et déverrouillée, qui l'enregistre et actualise le calendrier. Les commandes s'exécutent sur votre ordinateur, pas sur cette page web.",
  "kdm_limit_1": "Une demande d'agenda peut couvrir jusqu'à 31 jours et renvoyer jusqu'à 100 événements.",
  "kdm_limit_2": "La consultation de l'agenda ne peut pas déverrouiller un Killendar protégé par mot de passe.",
  "kdm_limit_3": "Créer un rendez-vous nécessite que Killendar soit ouvert et déverrouillé.",
  "kdm_limit_4": "La modification, la suppression et la création de rendez-vous récurrents passent toujours par l'interface de l'app.",
  "kdm_conn_title": "Une seule connexion pour toute la famille",
  "kdm_conn_1": "Installez KillerMCP une fois. Il détecte les apps Killer prises en charge sur votre ordinateur et ajoute leurs outils à une seule connexion d'agent. À mesure que de nouvelles intégrations sortent, le même moteur KillerMCP peut les fournir sans installateur séparé pour chaque app.",
  "mcp_nav_conn": "Une seule connexion",
  "kd_shot_1": "Vue mois, thème Delirium : un mois d'octobre complet, les événements sur toute la journée s'étendent en haut de chaque jour",
  "kd_shot_2": "Vue semaine, thème Decay : une semaine de travail de cinq jours, barre d'outils avec petites icônes et libellés à côté",
  "kd_shot_3": "Vue jour, thème 98SE : modification d'un rendez-vous dans le panneau latéral à côté de la grille horaire",
  "kd_shot_4": "Vue agenda, thème Blood : les jours à venir sous forme de liste, libellés sous les icônes, Film Grain désactivé",
  "kd_shot_5": "Semaines glissantes, thème Ectoplasm : trois semaines à partir de l'actuelle avec un zoom de 110 %",
