  "ui_platform": "Plattform",
  "ui_runtime": "Laufzeit",
  "contact_src_card": "Quellcode auf GitHub<span class=\"sub\">github.com/<wbr>SteveTheKiller</span>",
  "contact_issue_card": "Problem melden<span class=\"sub\">GitHub-Issues</span>",
  "kdm_hero": "Fragen Sie nach Ihrem Kalender oder fügen Sie einen Termin hinzu.",
  "kdm_intro": "KillerMCP enthält alle 81 KillerTools-Werkzeuge und dazu die Werkzeuge unterstützter Killer-Apps in einer einzigen lokalen Verbindung. Sie brauchen kein eigenes Killendar-Installationsprogramm, keinen Quellcode, kein Node und keine Befehlsliste.",
  "kdm_step_1": "<strong>KillerMCP Setup herunterladen und ausführen.</strong> Verwenden Sie das oben verlinkte signierte Installationsprogramm.",
  "kdm_step_2": "<strong>Das Setup Ihren Agenten verbinden lassen.</strong> Es installiert die gemeinsame Laufzeit und registriert KillerMCP bei Codex, Claude Code, Claude Desktop, Cursor, GitHub Copilot, Gemini CLI und Windsurf, sofern vorhanden.",
  "kdm_step_3": "<strong>Einen neuen Agenten-Chat öffnen und fragen.</strong> KillerMCP erkennt Killendar auf Ihrem Computer und stellt dessen Kalenderwerkzeuge über dieselbe Verbindung bereit.",
  "kdm_examples_intro": "<code>killer</code> ist die kürzeste Form. Ihr Agent erkennt Killendar, wenn es in der Anfrage eindeutig um Ihren Kalender geht. Verwenden Sie <code>killendar</code>, wenn Sie die App ausdrücklich nennen möchten.",
  "kdm_ex_1": "killer was steht heute in meinem Kalender",
  "kdm_ex_2": "killer zeige meine Termine diese Woche",
  "kdm_ex_3": "killendar was ist nächsten Freitag geplant",
  "kdm_ex_4": "killer liste meine nächsten 20 Kalendereinträge auf",
  "kdm_ex_5": "killer füge am 15. Oktober von 9 bis 10 Uhr einen Vor-Ort-Termin hinzu",
  "kdm_ex_6": "killendar füge am 15. Oktober einen ganztägigen Urlaub hinzu",
  "kdm_tools_intro": "KillerMCP liest den aktiven Kalender einschließlich wiederkehrender Termine und erstellt einzelne Termine über die laufende App.",
  "kdm_tool_1_t": "Ihre Agenda lesen",
  "kdm_tool_1_b": "Bis zu 31 Tage an Terminen sehen, ohne das Kalenderfenster zu öffnen.",
  "kdm_tool_2_t": "Wiederholungen verstehen",
  "kdm_tool_2_b": "Wiederkehrende Termine werden in die Daten innerhalb des angefragten Zeitraums aufgelöst.",
  "kdm_tool_3_t": "Termine erstellen",
  "kdm_tool_3_b": "Einen Termin mit Uhrzeit oder ganztägig hinzufügen, solange Killendar geöffnet und entsperrt ist.",
  "kdm_tool_4_t": "Bearbeiten bleibt in der App",
  "kdm_tool_4_b": "Bearbeiten, Löschen und das Einrichten wiederkehrender Termine geschehen weiterhin in Killendar.",
  "kdm_priv_1": "Die Agenda-Abfrage liest die lokale Datei, ohne sie zu ändern. Das Erstellen läuft über die geöffnete Killendar-App, daher aktualisiert sich ihr Kalender sofort. Ihr MCP-Client und dessen Modellanbieter können die Termindetails erhalten, die an diese Werkzeuge gesendet und von ihnen zurückgegeben werden.",
  "kdm_arch_1": "KillerMCP verbindet Ihren KI-Assistenten mit unterstützten Killer-Apps auf Ihrem Computer. Es findet Killendar und bietet ein Agenda-Werkzeug für begrenzte, reine Leseabfragen. Das Erstellwerkzeug sendet einen geprüften Termin an die laufende, entsperrte App, die ihn speichert und den Kalender aktualisiert. Die Befehle laufen auf Ihrem Computer, nicht auf dieser Webseite.",
  "kdm_limit_1": "Eine Agenda-Anfrage kann bis zu 31 Tage abdecken und bis zu 100 Termine liefern.",
  "kdm_limit_2": "Die Agenda-Abfrage kann kennwortgeschützte Killendars nicht entsperren.",
  "kdm_limit_3": "Zum Erstellen eines Termins muss Killendar geöffnet und entsperrt sein.",
  "kdm_limit_4": "Bearbeiten, Löschen und das Anlegen wiederkehrender Termine erfordern weiterhin die App-Oberfläche.",
  "kdm_conn_title": "Eine Verbindung für die ganze Familie",
  "kdm_conn_1": "Installieren Sie KillerMCP einmal. Es erkennt die unterstützten Killer-Apps auf Ihrem Computer und fügt ihre Werkzeuge einer einzigen Agentenverbindung hinzu. Wenn weitere App-Integrationen erscheinen, kann dieselbe KillerMCP-Laufzeit sie bereitstellen, ohne eigenes Installationsprogramm für jede App.",
  "mcp_nav_conn": "Eine Verbindung",
  "kd_shot_1": "Monatsansicht, Design Delirium: ein ganzer Oktober, ganztägige Termine laufen oben über jeden Tag",
