  "kd_shot_3": "Tagesansicht, Design 98SE: ein Termin wird in der Seitenleiste neben dem Stundenraster bearbeitet",
  "kd_shot_4": "Agendaansicht, Design Blood: die kommenden Tage als Liste, Beschriftungen unter den Symbolen, Film Grain aus",
