  "kdm_hero": "Ptejte se na svůj kalendář nebo přidejte schůzku.",
  "kdm_intro": "KillerMCP obsahuje všech 81 nástrojů KillerTools a navíc nástroje podporovaných aplikací Killer v jediném místním připojení. Nepotřebujete samostatný instalátor pro Killendar, zdrojový kód, Node ani seznam příkazů.",
  "kdm_step_1": "<strong>Stáhněte a spusťte KillerMCP Setup.</strong> Použijte podepsaný instalátor výše.",
  "kdm_step_2": "<strong>Nechte instalátor připojit agenta.</strong> Nainstaluje sdílené běhové prostředí a zaregistruje KillerMCP v Codexu, Claude Code, Claude Desktop, Cursoru, GitHub Copilotu, Gemini CLI a Windsurfu, pokud je najde.",
  "kdm_step_3": "<strong>Otevřete nový chat s agentem a zeptejte se.</strong> KillerMCP najde Killendar na vašem počítači a zpřístupní jeho kalendářové nástroje stejným připojením.",
  "kdm_examples_intro": "<code>killer</code> je nejkratší forma. Agent pozná Killendar, když se požadavek zjevně týká kalendáře. Použijte <code>killendar</code>, když chcete aplikaci uvést výslovně.",
