  "kdm_arch_1": "KillerMCP propojuje vašeho asistenta AI s podporovanými aplikacemi Killer na počítači. Najde Killendar a nabídne nástroj agendy pro omezené dotazy jen pro čtení. Nástroj pro vytváření pošle ověřenou schůzku spuštěné, odemčené aplikaci, která ji uloží a obnoví kalendář. Příkazy běží na vašem počítači, ne na této webové stránce.",
  "kdm_limit_1": "Dotaz na agendu může pokrýt až 31 dní a vrátit až 100 událostí.",
