  "kdm_hero": "Takviminizi sorun veya bir randevu ekleyin.",
  "kdm_intro": "KillerMCP, 81 KillerTools aracının tamamını ve desteklenen Killer uygulamalarının araçlarını tek bir yerel bağlantıda sunar. Ayrı bir Killendar yükleyicisine, kaynak koduna, Node'a veya komut listesine gerek yoktur.",
