  "kdm_examples_intro": "<code>killer</code> en kısa biçimdir. İstek açıkça takviminizle ilgili olduğunda ajanınız Killendar'ı anlar. Uygulamayı açıkça belirtmek istediğinizde <code>killendar</code> kullanın.",
