  "kdm_priv_1": "Ajanda sorgusu yerel dosyayı değiştirmeden okur. Oluşturma işlemi açık Killendar uygulaması üzerinden yapılır, bu yüzden takvim hemen güncellenir. MCP istemciniz ve model sağlayıcısı bu araçlara gönderilen ve onlardan dönen randevu ayrıntılarını alabilir.",
  "kdm_arch_1": "KillerMCP, yapay zekâ asistanınızı bilgisayarınızda kurulu desteklenen Killer uygulamalarına bağlar. Killendar'ı bulur ve sınırlı, salt okunur sorgular için bir ajanda aracı sunar. Oluşturma aracı, doğrulanmış bir randevuyu çalışan ve kilidi açık uygulamaya gönderir; uygulama onu kaydeder ve takvimi yeniler. Komutlar bu web sayfasında değil, bilgisayarınızda çalışır.",
  "kdm_limit_1": "Bir ajanda isteği en fazla 31 günü kapsayabilir ve en fazla 100 etkinlik döndürebilir.",
  "kdm_limit_2": "Ajanda sorgusu parola korumalı Killendar'ların kilidini açamaz.",
  "kdm_limit_3": "Randevu oluşturmak için Killendar'ın açık ve kilitsiz olması gerekir.",
