  "kdm_conn_title": "Tüm aile için tek bağlantı",
  "kdm_conn_1": "KillerMCP'yi bir kez kurun. Bilgisayarınızdaki desteklenen Killer uygulamalarını algılar ve araçlarını tek bir ajan bağlantısına ekler. Yeni entegrasyonlar çıktıkça aynı KillerMCP çalışma zamanı bunları her uygulama için ayrı bir yükleyici gerekmeden sunabilir.",
