  "mcp_nav_limits": "現在の制限",
  "mcp_gh": "GitHub の KillerMCP",
  "ui_version": "バージョン",
  "ui_released": "公開日",
  "ui_size": "サイズ",
  "ui_platform": "プラットフォーム",
  "ui_runtime": "ランタイム",
  "contact_src_card": "GitHub のソースコード<span class=\"sub\">github.com/<wbr>SteveTheKiller</span>",
  "contact_issue_card": "問題を報告<span class=\"sub\">GitHub の Issues</span>",
  "kdm_hero": "予定を尋ねたり、予定を追加したりできます。",
  "kdm_intro": "KillerMCP には KillerTools の 81 個のユーティリティすべてと、対応 Killer アプリのツールが 1 つのローカル接続にまとまっています。Killendar 専用のインストーラー、ソースコード、Node、コマンドの一覧は必要ありません。",
  "kdm_step_1": "<strong>KillerMCP Setup をダウンロードして実行します。</strong>上の署名付きインストーラーを使ってください。",
  "kdm_step_2": "<strong>セットアップにエージェントを接続させます。</strong>共有ランタイムをインストールし、見つかった Codex、Claude Code、Claude Desktop、Cursor、GitHub Copilot、Gemini CLI、Windsurf に KillerMCP を登録します。",
  "kdm_step_3": "<strong>エージェントとの新しいチャットを開いて質問します。</strong>KillerMCP がコンピューター上の Killendar を検出し、同じ接続でカレンダーのツールを使えるようにします。",
  "kdm_examples_intro": "<code>killer</code> が最も短い形です。依頼が明らかにカレンダーについてなら、エージェントは Killendar を使うと判断します。アプリを明示したいときは <code>killendar</code> を使います。",
  "kdm_ex_1": "killer 今日の予定は何",
  "kdm_ex_2": "killer 今週の予定を表示して",
  "kdm_ex_3": "killendar 次の金曜日に何が入っている",
  "kdm_ex_4": "killer 次の予定を 20 件一覧にして",
  "kdm_ex_5": "killer 10 月 15 日の 9 時から 10 時に現地訪問を追加して",
  "kdm_ex_6": "killendar 10 月 15 日に終日の休暇を追加して",
  "kdm_tools_intro": "KillerMCP は繰り返しの予定も含めて現在のカレンダーを読み取り、実行中のアプリを通じて単発の予定を作成します。",
  "kdm_tool_1_t": "予定表を読む",
  "kdm_tool_1_b": "カレンダーのウィンドウを開かずに、最大 31 日分の予定を確認できます。",
  "kdm_tool_2_t": "繰り返しを把握する",
  "kdm_tool_2_b": "繰り返しの予定は、指定した期間内の日付に展開されます。",
  "kdm_tool_3_t": "予定を作成する",
  "kdm_tool_3_b": "Killendar が開いていてロック解除されている間に、時刻指定または終日の予定を追加します。",
  "kdm_tool_4_t": "編集はアプリで",
  "kdm_tool_4_b": "予定の編集、削除、繰り返しの設定は、これまでどおり Killendar で行います。",
  "kdm_priv_1": "予定表の取得はローカル ファイルを変更せずに読み取ります。作成は開いている Killendar アプリを通じて行うので、カレンダーはすぐに更新されます。MCP クライアントとそのモデルの提供元は、これらのツールに送られ、ツールから返される予定の詳細を受け取る可能性があります。",
  "kdm_arch_1": "KillerMCP は、AI アシスタントをコンピューターにインストールされた対応 Killer アプリにつなぎます。Killendar を見つけ、範囲を限った読み取り専用の問い合わせ用に予定表ツールを提供します。作成ツールは検証済みの予定を、実行中でロック解除されたアプリに送り、アプリがそれを保存してカレンダーを更新します。コマンドはこの Web ページではなく、あなたのコンピューターで実行されます。",
  "kdm_limit_1": "予定表の取得は最大 31 日分、最大 100 件の予定までです。",
  "kdm_limit_2": "予定表の取得では、パスワードで保護された Killendar のロックは解除できません。",
  "kdm_limit_3": "予定を作成するには、Killendar が開いていてロック解除されている必要があります。",
  "kdm_limit_4": "予定の編集、削除、繰り返しの予定の作成には、引き続きアプリの画面が必要です。",
  "kdm_conn_title": "ファミリー全体で 1 つの接続",
  "kdm_conn_1": "KillerMCP を一度インストールするだけです。コンピューター上の対応 Killer アプリを検出し、それらのツールを 1 つのエージェント接続に追加します。アプリの連携が増えても、同じ KillerMCP ランタイムで提供でき、アプリごとのインストーラーは要りません。",
  "mcp_nav_conn": "1 つの接続",
  "kd_shot_1": "月表示、Delirium テーマ: 10 月をまるごと表示し、終日の予定が各日の上部に並ぶ",
  "kd_shot_2": "週表示、Decay テーマ: 5 日間の勤務週、小さいアイコンの横にラベルが付くツールバー",
  "kd_shot_3": "日表示、98SE テーマ: 時間グリッドの横のサイドバーで予定を編集中",
  "kd_shot_4": "予定表表示、Blood テーマ: これからの日々を一覧で表示、アイコンの下にラベル、Film Grain オフ",
