  "kd_shot_7": "バージョン情報カード、Sepulchre テーマ: アプリのズーム 120% でバージョン、署名、ビルドの詳細、テキストのみのツールバー",
  "kd_shot_8": "月表示、赤のアクセントの Light テーマ、Film Grain オフ",
