  "kdm_hero": "询问你的日历，或添加一个约会。",
  "kdm_intro": "KillerMCP 在一个本地连接中包含全部 81 个 KillerTools 实用工具，以及受支持 Killer 应用的工具。你不需要单独的 Killendar 安装程序、源代码、Node 或命令列表。",
  "kdm_step_1": "<strong>下载并运行 KillerMCP Setup。</strong>使用上面的已签名安装程序。",
  "kdm_step_2": "<strong>让安装程序连接你的代理。</strong>它会安装共享运行时，并在找到 Codex、Claude Code、Claude Desktop、Cursor、GitHub Copilot、Gemini CLI 和 Windsurf 时为它们注册 KillerMCP。",
  "kdm_step_3": "<strong>与代理开启新对话并提问。</strong>KillerMCP 会检测电脑上的 Killendar，并通过同一个连接提供它的日历工具。",
  "kdm_examples_intro": "<code>killer</code> 是最短的写法。只要请求明显与你的日历有关，代理就能判断要用 Killendar。想明确指定应用时，请使用 <code>killendar</code>。",
