  "kdm_ex_6": "killendar 在 10 月 15 日添加全天休假",
  "kdm_tools_intro": "KillerMCP 读取当前日历（包括重复事件），并通过正在运行的应用创建单次约会。",
  "kdm_tool_1_t": "读取日程",
  "kdm_tool_1_b": "无需打开日历窗口即可查看最多 31 天的事件。",
  "kdm_tool_2_t": "理解重复规则",
  "kdm_tool_2_b": "重复约会会展开为请求范围内的各个日期。",
  "kdm_tool_3_t": "创建约会",
  "kdm_tool_3_b": "在 Killendar 打开且已解锁时，添加定时或全天约会。",
  "kdm_tool_4_t": "编辑仍在应用中进行",
