  "kdm_priv_1": "日程查询只读取本地文件，不会更改它。创建操作通过已打开的 Killendar 应用进行，因此日历会立即更新。你的 MCP 客户端及其模型提供商可能会收到发送给这些工具以及由它们返回的约会详情。",
  "kdm_arch_1": "KillerMCP 将你的 AI 助手连接到电脑上已安装的受支持 Killer 应用。它会找到 Killendar，并提供一个用于有限只读查询的日程工具。创建工具会把经过验证的约会发送给正在运行且已解锁的应用，由应用保存并刷新日历。这些命令在你的电脑上运行，而不是在本网页上。",
  "kdm_limit_1": "一次日程请求最多覆盖 31 天，最多返回 100 个事件。",
  "kdm_limit_2": "日程查询无法解锁受密码保护的 Killendar。",
