  "contact_issue_card": "Сообщить о проблеме<span class=\"sub\">задачи на GitHub</span>",
  "kdm_hero": "Спросите о своём календаре или добавьте встречу.",
  "kdm_intro": "KillerMCP объединяет все 81 утилиту KillerTools и инструменты поддерживаемых приложений Killer в одном локальном подключении. Не нужны ни отдельный установщик Killendar, ни исходный код, ни Node, ни список команд.",
  "kdm_step_1": "<strong>Скачайте и запустите KillerMCP Setup.</strong> Используйте подписанный установщик выше.",
  "kdm_step_2": "<strong>Позвольте установщику подключить агента.</strong> Он устанавливает общую среду выполнения и регистрирует KillerMCP в Codex, Claude Code, Claude Desktop, Cursor, GitHub Copilot, Gemini CLI и Windsurf, если находит их.",
  "kdm_step_3": "<strong>Откройте новый чат с агентом и задайте вопрос.</strong> KillerMCP находит Killendar на вашем компьютере и делает его инструменты календаря доступными через то же подключение.",
  "kdm_examples_intro": "<code>killer</code> это самая короткая форма. Агент поймёт, что нужен Killendar, если запрос явно касается вашего календаря. Используйте <code>killendar</code>, если хотите назвать приложение явно.",
  "kdm_ex_1": "killer что у меня сегодня в календаре",
  "kdm_ex_2": "killer покажи мои встречи на этой неделе",
  "kdm_ex_3": "killendar что запланировано на следующую пятницу",
  "kdm_ex_4": "killer покажи мои ближайшие 20 событий",
  "kdm_ex_5": "killer добавь выезд к клиенту 15 октября с 9 до 10",
  "kdm_ex_6": "killendar добавь отпуск на весь день 15 октября",
  "kdm_tools_intro": "KillerMCP читает активный календарь, включая повторяющиеся события, и создаёт отдельные встречи через запущенное приложение.",
  "kdm_tool_1_t": "Чтение расписания",
  "kdm_tool_1_b": "Просматривайте события на срок до 31 дня, не открывая окно календаря.",
  "kdm_tool_2_t": "Понимание повторений",
  "kdm_tool_2_b": "Повторяющиеся встречи разворачиваются в даты внутри запрошенного периода.",
  "kdm_tool_3_t": "Создание встреч",
  "kdm_tool_3_b": "Добавляйте встречу со временем или на весь день, пока Killendar открыт и разблокирован.",
  "kdm_tool_4_t": "Правка остаётся в приложении",
  "kdm_tool_4_b": "Правка, удаление и настройка повторяющихся встреч по-прежнему выполняются в Killendar.",
  "kdm_priv_1": "Запрос повестки читает локальный файл, не изменяя его. Создание проходит через открытое приложение Killendar, поэтому календарь обновляется сразу. Ваш клиент MCP и его поставщик модели могут получать сведения о встречах, отправляемые этим инструментам и возвращаемые ими.",
  "kdm_arch_1": "KillerMCP связывает ИИ-помощника с поддерживаемыми приложениями Killer, установленными на компьютере. Он находит Killendar и предлагает инструмент повестки для ограниченных запросов только на чтение. Инструмент создания отправляет проверенную встречу запущенному разблокированному приложению, которое сохраняет её и обновляет календарь. Команды выполняются на вашем компьютере, а не на этой веб-странице.",
  "kdm_limit_1": "Запрос повестки может охватывать до 31 дня и возвращать до 100 событий.",
  "kdm_limit_2": "Запрос повестки не может разблокировать Killendar, защищённые паролем.",
  "kdm_limit_3": "Для создания встречи Killendar должен быть открыт и разблокирован.",
  "kdm_limit_4": "Правка, удаление и создание повторяющихся встреч по-прежнему требуют интерфейса приложения.",
  "kdm_conn_title": "Одно подключение для всего семейства",
  "kdm_conn_1": "Установите KillerMCP один раз. Он находит поддерживаемые приложения Killer на компьютере и добавляет их инструменты в одно подключение агента. По мере выхода новых интеграций та же среда KillerMCP сможет предоставлять их без отдельного установщика для каждого приложения.",
  "mcp_nav_conn": "Одно подключение",
  "kd_shot_1": "Вид месяца, тема Delirium: весь октябрь, события на весь день тянутся по верху каждого дня",
  "kd_shot_2": "Вид недели, тема Decay: пятидневная рабочая неделя, панель инструментов с маленькими значками и подписями рядом",
  "kd_shot_3": "Вид дня, тема 98SE: правка встречи на боковой панели рядом с почасовой сеткой",
