  "kdm_intro": "KillerMCP барлық 81 KillerTools құралын және қолдау көрсетілетін Killer қолданбаларының құралдарын бір жергілікті қосылымда біріктіреді. Бөлек Killendar орнатқышы, бастапқы код, Node немесе пәрмендер тізімі қажет емес.",
