  "kdm_examples_intro": "<code>killer</code> ең қысқа түрі. Сұрау анық күнтізбеңіз туралы болса, агент Killendar керек екенін түсінеді. Қолданбаны нақты атағыңыз келсе, <code>killendar</code> пайдаланыңыз.",
