  "kdm_arch_1": "KillerMCP з’єднує ШІ-помічника з підтримуваними застосунками Killer, встановленими на комп’ютері. Він знаходить Killendar і пропонує інструмент розкладу для обмежених запитів лише на читання. Інструмент створення надсилає перевірену зустріч запущеному розблокованому застосунку, який зберігає її й оновлює календар. Команди виконуються на вашому комп’ютері, а не на цій вебсторінці.",
