  "kdm_tool_3_t": "Opprett avtaler",
  "kdm_tool_3_b": "Legg til en avtale med klokkeslett eller for hele dagen mens Killendar er åpen og ulåst.",
  "kdm_tool_4_t": "Redigering skjer i appen",
  "kdm_tool_4_b": "Redigering, sletting og oppsett av gjentakende avtaler skjer fortsatt i Killendar.",
  "kdm_priv_1": "Agendaoppslaget leser den lokale filen uten å endre den. Oppretting går gjennom den åpne Killendar-appen, så kalenderen oppdateres med en gang. MCP-klienten og modelleverandøren kan motta avtaledetaljene som sendes til og returneres fra disse verktøyene.",
  "kdm_arch_1": "KillerMCP kobler KI-assistenten din til støttede Killer-apper på datamaskinen. Den finner Killendar og tilbyr et agendaverktøy for begrensede, skrivebeskyttede oppslag. Opprettingsverktøyet sender en kontrollert avtale til den kjørende, ulåste appen, som lagrer den og oppdaterer kalenderen. Kommandoene kjører på datamaskinen din, ikke på denne nettsiden.",
  "kdm_limit_1": "En agendaforespørsel kan dekke opptil 31 dager og returnere opptil 100 hendelser.",
  "kdm_limit_2": "Agendaoppslaget kan ikke låse opp passordbeskyttede Killendars.",
  "kdm_limit_3": "For å opprette en avtale må Killendar være åpen og ulåst.",
  "kdm_limit_4": "Redigering, sletting og oppretting av gjentakende avtaler krever fortsatt appens grensesnitt.",
  "kdm_conn_title": "Én tilkobling for hele familien",
  "kdm_conn_1": "Installer KillerMCP én gang. Den finner støttede Killer-apper på datamaskinen din og legger verktøyene deres til én agenttilkobling. Etter hvert som flere integrasjoner kommer, kan den samme KillerMCP-kjøretiden levere dem uten et eget installasjonsprogram for hver app.",
  "mcp_nav_conn": "Én tilkobling",
  "kd_shot_1": "Månedsvisning, temaet Delirium: en hel oktober, heldagshendelser strekker seg over toppen av hver dag",
  "kd_shot_2": "Ukevisning, temaet Decay: en arbeidsuke på fem dager, verktøylinje med små ikoner og etiketter ved siden av",
  "kd_shot_3": "Dagsvisning, temaet 98SE: en avtale redigeres i sidepanelet ved siden av timerutenettet",
  "kd_shot_4": "Agendavisning, temaet Blood: de kommende dagene som en liste, etiketter under ikonene, Film Grain av",
  "kd_shot_5": "Rullende uker, temaet Ectoplasm: tre uker fra den inneværende med 110 % zoom i appen",
  "kd_shot_6": "Hurtigtaster, temaet Black med turkis aksent: F1-overlegget med hver tast på et tegnet tastatur",
