  "contact_src_card": "Código-fonte no GitHub<span class=\"sub\">github.com/<wbr>SteveTheKiller</span>",
  "contact_issue_card": "Relatar um problema<span class=\"sub\">issues do GitHub</span>",
  "kdm_hero": "Pergunte sobre sua agenda ou adicione um compromisso.",
  "kdm_intro": "O KillerMCP inclui os 81 utilitários do KillerTools e as ferramentas dos apps Killer compatíveis em uma única conexão local. Você não precisa de um instalador separado do Killendar, do código-fonte, do Node nem de uma lista de comandos.",
  "kdm_step_1": "<strong>Baixe e execute o KillerMCP Setup.</strong> Use o instalador assinado acima.",
  "kdm_step_2": "<strong>Deixe o instalador conectar seu agente.</strong> Ele instala o runtime compartilhado e registra o KillerMCP no Codex, Claude Code, Claude Desktop, Cursor, GitHub Copilot, Gemini CLI e Windsurf quando os encontra.",
  "kdm_step_3": "<strong>Abra um novo chat com o agente e pergunte.</strong> O KillerMCP detecta o Killendar no seu computador e disponibiliza as ferramentas de agenda pela mesma conexão.",
  "kdm_examples_intro": "<code>killer</code> é a forma mais curta. Seu agente reconhece o Killendar quando o pedido é claramente sobre sua agenda. Use <code>killendar</code> quando quiser citar o app explicitamente.",
  "kdm_ex_1": "killer o que tenho na agenda hoje",
  "kdm_ex_2": "killer mostre meus compromissos desta semana",
  "kdm_ex_3": "killendar o que está marcado para a próxima sexta",
  "kdm_ex_4": "killer liste meus próximos 20 eventos",
  "kdm_ex_5": "killer adicione uma visita técnica em 15 de outubro das 9h às 10h",
  "kdm_ex_6": "killendar adicione férias o dia todo em 15 de outubro",
  "kdm_tools_intro": "O KillerMCP lê a agenda ativa, incluindo eventos recorrentes, e cria compromissos avulsos pelo app em execução.",
  "kdm_tool_1_t": "Ler sua agenda",
  "kdm_tool_1_b": "Ver até 31 dias de eventos sem abrir a janela da agenda.",
  "kdm_tool_2_t": "Entender recorrências",
  "kdm_tool_2_b": "Compromissos recorrentes são expandidos nas datas dentro do intervalo pedido.",
  "kdm_tool_3_t": "Criar compromissos",
  "kdm_tool_3_b": "Adicionar um compromisso com horário ou de dia inteiro enquanto o Killendar está aberto e desbloqueado.",
  "kdm_tool_4_t": "Edições ficam no app",
  "kdm_tool_4_b": "Editar, excluir e configurar compromissos recorrentes continuam sendo feitos no Killendar.",
  "kdm_priv_1": "A consulta da agenda lê o arquivo local sem alterá-lo. A criação passa pelo app Killendar aberto, então a agenda se atualiza na hora. Seu cliente MCP e o provedor do modelo podem receber os detalhes dos compromissos enviados a essas ferramentas e devolvidos por elas.",
  "kdm_arch_1": "O KillerMCP conecta seu assistente de IA aos apps Killer compatíveis instalados no seu computador. Ele encontra o Killendar e oferece uma ferramenta de agenda para consultas limitadas e somente leitura. A ferramenta de criação envia um compromisso validado ao app em execução e desbloqueado, que o salva e atualiza a agenda. Os comandos rodam no seu computador, não nesta página.",
  "kdm_limit_1": "Uma consulta de agenda pode cobrir até 31 dias e retornar até 100 eventos.",
  "kdm_limit_2": "A consulta da agenda não consegue desbloquear Killendars protegidos por senha.",
  "kdm_limit_3": "Para criar um compromisso, o Killendar precisa estar aberto e desbloqueado.",
  "kdm_limit_4": "Editar, excluir e criar compromissos recorrentes ainda exige a interface do app.",
  "kdm_conn_title": "Uma conexão para toda a família",
  "kdm_conn_1": "Instale o KillerMCP uma vez. Ele detecta os apps Killer compatíveis no seu computador e adiciona as ferramentas deles a uma única conexão do agente. À medida que novas integrações forem lançadas, o mesmo runtime do KillerMCP poderá oferecê-las sem um instalador separado para cada app.",
  "mcp_nav_conn": "Uma conexão",
  "kd_shot_1": "Visualização do mês, tema Delirium: um outubro inteiro, eventos de dia inteiro atravessando o topo de cada dia",
  "kd_shot_2": "Visualização da semana, tema Decay: uma semana útil de cinco dias, barra de ferramentas com ícones pequenos e rótulos ao lado",
  "kd_shot_3": "Visualização do dia, tema 98SE: edição de um compromisso no painel lateral ao lado da grade de horas",
  "kd_shot_4": "Visualização de agenda, tema Blood: os próximos dias em lista, rótulos sob os ícones, Film Grain desligado",
  "kd_shot_5": "Semanas contínuas, tema Ectoplasm: três semanas a partir da atual com zoom de 110%",
  "kd_shot_6": "Atalhos de teclado, tema Black com destaque turquesa: a sobreposição do F1 com cada atalho em um teclado desenhado",
