// Why KillerMCP runs twice (mcp.html).
if (I18N["vi"]) Object.assign(I18N["vi"], {"mcp_nav_processes":"Hai tiến trình","mcp_processes_title":"Vì sao <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> chạy hai lần","mcp_processes_body":"Claude Desktop khởi động mỗi máy chủ MCP cục bộ hai lần. Một bản phục vụ các cuộc trò chuyện của chính ứng dụng, bản còn lại phục vụ các phiên Claude sử dụng máy tính này từ xa. Vì vậy, việc thấy hai tiến trình KillerMCP.exe dưới Claude trong Trình quản lý Tác vụ là bình thường. KillerMCP không bị cài đặt hai lần và không có gì cần sửa."});
if (I18N["hu"]) Object.assign(I18N["hu"], {"mcp_nav_processes":"Két folyamat","mcp_processes_title":"Miért fut kétszer a <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span>","mcp_processes_body":"A Claude Desktop minden helyi MCP-kiszolgálót kétszer indít el. Az egyik példány az alkalmazás saját csevegéseit szolgálja ki, a másik pedig azokat a Claude-munkameneteket, amelyek távolról használják ezt a számítógépet. Ezért normális, ha a Feladatkezelőben a Claude alatt két KillerMCP.exe folyamat látható. A KillerMCP nincs kétszer telepítve, és semmit sem kell javítani."});
if (I18N["es"]) Object.assign(I18N["es"], {"mcp_nav_processes":"Dos procesos","mcp_processes_title":"Por qué <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> se ejecuta dos veces","mcp_processes_body":"Claude Desktop inicia cada servidor MCP local dos veces. Una copia atiende los chats de la propia aplicación y la otra atiende las sesiones de Claude que usan este equipo de forma remota. Por eso es normal ver dos procesos KillerMCP.exe bajo Claude en el Administrador de tareas. KillerMCP no está instalado dos veces y no hay nada que corregir."});
if (I18N["fr"]) Object.assign(I18N["fr"], {"mcp_nav_processes":"Deux processus","mcp_processes_title":"Pourquoi <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> s'exécute deux fois","mcp_processes_body":"Claude Desktop démarre chaque serveur MCP local deux fois. Une copie sert les conversations de l'application elle-même, et l'autre sert les sessions Claude qui utilisent cet ordinateur à distance. Il est donc normal de voir deux processus KillerMCP.exe sous Claude dans le Gestionnaire des tâches. KillerMCP n'est pas installé deux fois, et il n'y a rien à corriger."});
if (I18N["de"]) Object.assign(I18N["de"], {"mcp_nav_processes":"Zwei Prozesse","mcp_processes_title":"Warum <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> zweimal läuft","mcp_processes_body":"Claude Desktop startet jeden lokalen MCP-Server zweimal. Eine Kopie bedient die Chats der App selbst, die andere bedient Claude-Sitzungen, die diesen Computer aus der Ferne nutzen. Zwei KillerMCP.exe-Prozesse unter Claude im Task-Manager sind daher normal. KillerMCP ist nicht doppelt installiert, und es muss nichts behoben werden."});
if (I18N["cs"]) Object.assign(I18N["cs"], {"mcp_nav_processes":"Dva procesy","mcp_processes_title":"Proč <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> běží dvakrát","mcp_processes_body":"Claude Desktop spouští každý místní server MCP dvakrát. Jedna kopie obsluhuje chaty samotné aplikace a druhá obsluhuje relace Claude, které tento počítač používají vzdáleně. Dva procesy KillerMCP.exe pod Claude ve Správci úloh jsou proto normální. KillerMCP není nainstalován dvakrát a není potřeba nic opravovat."});
if (I18N["tr"]) Object.assign(I18N["tr"], {"mcp_nav_processes":"İki işlem","mcp_processes_title":"<span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> neden iki kez çalışıyor","mcp_processes_body":"Claude Desktop her yerel MCP sunucusunu iki kez başlatır. Kopyalardan biri uygulamanın kendi sohbetlerine, diğeri ise bu bilgisayarı uzaktan kullanan Claude oturumlarına hizmet eder. Bu nedenle Görev Yöneticisi'nde Claude altında iki KillerMCP.exe işlemi görmek normaldir. KillerMCP iki kez yüklenmemiştir ve düzeltilmesi gereken bir şey yoktur."});
if (I18N["ja"]) Object.assign(I18N["ja"], {"mcp_nav_processes":"2 つのプロセス","mcp_processes_title":"<span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> が 2 つ実行される理由","mcp_processes_body":"Claude Desktop は各ローカル MCP サーバーを 2 回起動します。1 つはアプリ自体のチャットを処理し、もう 1 つはこのコンピューターをリモートで使用する Claude セッションを処理します。そのため、タスク マネージャーで Claude の下に KillerMCP.exe のプロセスが 2 つ表示されるのは正常です。KillerMCP が二重にインストールされているわけではなく、修正の必要はありません。"});
if (I18N["pl"]) Object.assign(I18N["pl"], {"mcp_nav_processes":"Dwa procesy","mcp_processes_title":"Dlaczego <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> działa dwa razy","mcp_processes_body":"Claude Desktop uruchamia każdy lokalny serwer MCP dwa razy. Jedna kopia obsługuje czaty samej aplikacji, a druga obsługuje sesje Claude, które korzystają z tego komputera zdalnie. Dlatego dwa procesy KillerMCP.exe pod Claude w Menedżerze zadań to normalna sytuacja. KillerMCP nie jest zainstalowany dwa razy i nie trzeba niczego naprawiać."});
if (I18N["bn"]) Object.assign(I18N["bn"], {"mcp_nav_processes":"দুটি প্রসেস","mcp_processes_title":"<span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> কেন দুবার চলে","mcp_processes_body":"Claude Desktop প্রতিটি লোকাল MCP সার্ভার দুবার চালু করে। একটি কপি অ্যাপের নিজস্ব চ্যাট পরিচালনা করে, আর অন্যটি সেই Claude সেশনগুলো পরিচালনা করে যেগুলো এই কম্পিউটার দূর থেকে ব্যবহার করে। তাই টাস্ক ম্যানেজারে Claude-এর নিচে দুটি KillerMCP.exe প্রসেস দেখা স্বাভাবিক। KillerMCP দুবার ইনস্টল হয়নি, এবং কিছু ঠিক করার প্রয়োজন নেই।"});
if (I18N["zh-CN"]) Object.assign(I18N["zh-CN"], {"mcp_nav_processes":"两个进程","mcp_processes_title":"为什么 <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> 会运行两次","mcp_processes_body":"Claude Desktop 会将每个本地 MCP 服务器启动两次。一个副本服务于应用自身的聊天，另一个服务于远程使用这台计算机的 Claude 会话。因此，在任务管理器中看到 Claude 下有两个 KillerMCP.exe 进程是正常的。KillerMCP 并没有安装两次，也不需要修复任何问题。"});
if (I18N["zh-TW"]) Object.assign(I18N["zh-TW"], {"mcp_nav_processes":"兩個處理程序","mcp_processes_title":"為什麼 <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> 會執行兩次","mcp_processes_body":"Claude Desktop 會將每個本機 MCP 伺服器啟動兩次。一個副本負責應用程式本身的聊天，另一個負責從遠端使用這台電腦的 Claude 工作階段。因此，在工作管理員中看到 Claude 底下有兩個 KillerMCP.exe 處理程序是正常的。KillerMCP 並沒有安裝兩次，也不需要修正任何問題。"});
if (I18N["it"]) Object.assign(I18N["it"], {"mcp_nav_processes":"Due processi","mcp_processes_title":"Perché <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> viene eseguito due volte","mcp_processes_body":"Claude Desktop avvia ogni server MCP locale due volte. Una copia serve le chat dell'app stessa e l'altra serve le sessioni di Claude che usano questo computer da remoto. È quindi normale vedere due processi KillerMCP.exe sotto Claude in Gestione attività. KillerMCP non è installato due volte e non c'è nulla da correggere."});
if (I18N["ru"]) Object.assign(I18N["ru"], {"mcp_nav_processes":"Два процесса","mcp_processes_title":"Почему <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> запущен дважды","mcp_processes_body":"Claude Desktop запускает каждый локальный MCP-сервер дважды. Одна копия обслуживает чаты самого приложения, а другая обслуживает сеансы Claude, которые используют этот компьютер удаленно. Поэтому в диспетчере задач под Claude нормально видеть два процесса KillerMCP.exe. KillerMCP не установлен дважды, и ничего исправлять не нужно."});
if (I18N["kk"]) Object.assign(I18N["kk"], {"mcp_nav_processes":"Екі процесс","mcp_processes_title":"<span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> неге екі рет іске қосылады","mcp_processes_body":"Claude Desktop әр жергілікті MCP серверін екі рет іске қосады. Бір көшірмесі қолданбаның өз чаттарына қызмет етеді, ал екіншісі осы компьютерді қашықтан пайдаланатын Claude сеанстарына қызмет етеді. Сондықтан Тапсырмалар диспетчерінде Claude астында екі KillerMCP.exe процесін көру қалыпты жағдай. KillerMCP екі рет орнатылмаған және ештеңені түзетудің қажеті жоқ."});
if (I18N["uk"]) Object.assign(I18N["uk"], {"mcp_nav_processes":"Два процеси","mcp_processes_title":"Чому <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> запущено двічі","mcp_processes_body":"Claude Desktop запускає кожен локальний MCP-сервер двічі. Одна копія обслуговує чати самої програми, а інша обслуговує сеанси Claude, які використовують цей комп'ютер віддалено. Тому в диспетчері завдань під Claude нормально бачити два процеси KillerMCP.exe. KillerMCP не встановлено двічі, і нічого виправляти не потрібно."});
if (I18N["nb"]) Object.assign(I18N["nb"], {"mcp_nav_processes":"To prosesser","mcp_processes_title":"Hvorfor <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> kjører to ganger","mcp_processes_body":"Claude Desktop starter hver lokale MCP-server to ganger. Den ene kopien betjener appens egne chatter, og den andre betjener Claude-økter som bruker denne datamaskinen eksternt. Det er derfor normalt å se to KillerMCP.exe-prosesser under Claude i Oppgavebehandling. KillerMCP er ikke installert to ganger, og ingenting må rettes."});
if (I18N["pt"]) Object.assign(I18N["pt"], {"mcp_nav_processes":"Dois processos","mcp_processes_title":"Por que o <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> é executado duas vezes","mcp_processes_body":"O Claude Desktop inicia cada servidor MCP local duas vezes. Uma cópia atende os chats do próprio aplicativo e a outra atende as sessões do Claude que usam este computador remotamente. Por isso, é normal ver dois processos KillerMCP.exe sob o Claude no Gerenciador de Tarefas. O KillerMCP não está instalado duas vezes e não há nada para corrigir."});
