  "kdm_hero": "Vprašaj o svojem koledarju ali dodaj dogodek.",
  "mcp_install_title": "Namesti <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span>",
  "kdm_intro": "KillerMCP združuje vseh 81 pripomočkov KillerTools in orodja podprtih programov Killer v eni lokalni povezavi. Ne potrebuješ ločenega namestitvenega programa za Killendar, izvorne kode, Node ali seznama ukazov.",
  "mcp_download": "Prenesi za Windows",
  "mcp_signed": "Digitalno podpisano",
  "mcp_github_release": "Na voljo na GitHub Releases",
  "kdm_step_1": "<strong>Prenesi in zaženi namestitveni program KillerMCP.</strong> Uporabi zgornji podpisani namestitveni program.",
  "kdm_step_2": "<strong>Dovoli namestitvenemu programu, da poveže tvojega agenta.</strong> Namesti skupno izvajalno okolje in registrira KillerMCP v najdenih programih Codex, Claude Code, Claude Desktop, Cursor, GitHub Copilot, Gemini CLI in Windsurf.",
  "kdm_step_3": "<strong>Odpri nov pogovor z agentom in zastavi vprašanje.</strong> KillerMCP zazna Killendar v računalniku in prek iste povezave omogoči koledarska orodja.",
  "mcp_examples_title": "Poskusi vprašati",
  "kdm_examples_intro": "<code>killer</code> je najkrajša oblika. Agent lahko izbere Killendar, kadar se zahteva jasno nanaša na koledar. Za izrecno izbiro programa uporabi <code>killendar</code>.",
  "kdm_ex_1": "killer kaj imam danes na koledarju",
  "kdm_ex_2": "killer prikaži moje dogodke ta teden",
  "kdm_ex_3": "killendar kaj je načrtovano za naslednji petek",
  "kdm_ex_4": "killer naštej naslednjih 20 dogodkov v koledarju",
  "kdm_ex_5": "killer dodaj obisk lokacije 15. oktobra od 9. do 10. ure",
  "kdm_ex_6": "killendar dodaj celodnevni dopust 15. oktobra",
  "mcp_tools_title": "Kaj zmore",
  "kdm_tools_intro": "KillerMCP bere aktivni koledar, vključno s ponavljajočimi se dogodki, in prek zagnanega programa ustvarja posamezne dogodke.",
  "kdm_tool_1_t": "Preberi dnevni red",
  "kdm_tool_1_b": "Preglej dogodke za največ 31 dni brez odpiranja okna koledarja.",
  "kdm_tool_2_t": "Upoštevaj ponavljanje",
  "kdm_tool_2_b": "Ponavljajoči se dogodki se razširijo na posamezne datume znotraj zahtevanega obsega.",
  "kdm_tool_3_t": "Ustvari dogodke",
  "kdm_tool_3_b": "Dodaj dogodek z uro ali celodnevni dogodek, ko je Killendar odprt in odklenjen.",
  "kdm_tool_4_t": "Urejaj v programu",
  "kdm_tool_4_b": "Urejanje, brisanje in nastavljanje ponavljajočih se dogodkov še vedno potekajo v programu Killendar.",
  "mcp_privacy_title": "Varnost podatkov in dovoljenja",
  "kdm_priv_1": "Poizvedba po dnevnem redu bere lokalno datoteko brez sprememb. Ustvarjanje poteka prek odprtega programa Killendar, zato se koledar takoj posodobi. Tvoj odjemalec MCP in ponudnik njegovega modela lahko prejmeta podatke o dogodkih, poslane tem orodjem in vrnjene iz njih.",
  "mcp_arch_title": "Kako deluje",
  "kdm_arch_1": "KillerMCP poveže tvojega pomočnika AI s podprtimi programi Killer v računalniku. Najde Killendar in omogoči omejene poizvedbe po dnevnem redu samo za branje. Orodje za ustvarjanje pošlje preverjeni dogodek zagnanemu in odklenjenemu programu, ki ga shrani in osveži koledar. Ukazi se izvajajo v tvojem računalniku.",
  "mcp_limits_title": "Trenutne omejitve",
  "kdm_limit_1": "Poizvedba po dnevnem redu lahko zajame največ 31 dni in vrne največ 100 dogodkov.",
  "kdm_limit_2": "Poizvedba po dnevnem redu ne more odkleniti koledarjev Killendar, zaščitenih z geslom.",
  "kdm_limit_3": "Za ustvarjanje dogodka mora biti Killendar odprt in odklenjen.",
  "kdm_limit_4": "Urejanje, brisanje in ustvarjanje ponavljajočih se dogodkov še vedno zahtevajo vmesnik programa.",
  "mcp_processes_title": "Zakaj se <span class=\"killermcp-wordmark\">Killer<span class=\"killermcp-accent\">MCP</span></span> izvaja dvakrat",
  "mcp_processes_body": "Claude Desktop zažene vsak lokalni strežnik MCP dvakrat. Ena kopija podpira pogovore v programu, druga pa seje Claude, ki ta računalnik uporabljajo na daljavo. Dva procesa KillerMCP.exe pod programom Claude v Upravitelju opravil sta običajna. KillerMCP ni nameščen dvakrat in ničesar ni treba popravljati.",
  "kdm_conn_title": "Ena povezava za celotno zbirko",
  "kdm_conn_1": "KillerMCP namestiš enkrat. Zazna podprte programe Killer v računalniku in doda njihova orodja v eno povezavo z agentom. Ko so izdane nove integracije, jih lahko zagotovi isto izvajalno okolje KillerMCP brez ločenega namestitvenega programa za vsako aplikacijo.",
