// 1.4.0 technical page: per-appointment time zones, what calendar files carry, and the other tables in a .kcal.
if (I18N["en"]) Object.assign(I18N["en"], {"tk_kd_zones": "An appointment can also keep a time zone of its own, once <b>Show time zones</b> is ticked in the date settings. Its times are typed on that zone's clock and stored with the zone's name, so a 9:00 meeting in Tokyo stays at 9:00 there when either place changes its clocks.", "tk_kd_ics_more": "Repeats go out as <b>RRULE</b>, including the first to fourth or last weekday of a month, with extra dates as <b>RDATE</b> and skipped ones as <b>EXDATE</b>. Time zones travel with their <b>VTIMEZONE</b> definitions, and a file's own definition is read when Windows does not know the name. A newer invite for a meeting already here (a higher <b>SEQUENCE</b>) updates it and a cancellation removes it, after the import asks.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> and <b>reminder_state</b> - Recently deleted for 30 days, saved templates, and which reminders were dismissed or snoozed. Daily backups go to a <b>Backups</b> folder beside the file."});
if (I18N["vi"]) Object.assign(I18N["vi"], {"tk_kd_zones": "Một cuộc hẹn cũng có thể giữ múi giờ riêng khi bật <b>Hiện múi giờ</b> trong cài đặt ngày. Giờ được nhập theo đồng hồ của múi giờ đó và lưu kèm tên múi giờ, nên cuộc họp 9:00 ở Tokyo vẫn là 9:00 ở đó khi một trong hai nơi đổi giờ.", "tk_kd_ics_more": "Lịch lặp được xuất dưới dạng <b>RRULE</b>, kể cả ngày thứ nhất đến thứ tư hoặc cuối cùng trong tháng, ngày thêm dưới dạng <b>RDATE</b> và ngày bỏ qua dưới dạng <b>EXDATE</b>. Múi giờ đi kèm định nghĩa <b>VTIMEZONE</b>, và định nghĩa riêng của tệp được đọc khi Windows không biết tên đó. Lời mời mới hơn cho cuộc họp đã có (<b>SEQUENCE</b> cao hơn) sẽ cập nhật nó và lời hủy sẽ xóa nó, sau khi ứng dụng hỏi.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> và <b>reminder_state</b> - mục đã xóa gần đây trong 30 ngày, mẫu đã lưu, và lời nhắc nào đã bỏ qua hoặc tạm hoãn. Bản sao lưu hằng ngày nằm trong thư mục <b>Backups</b> cạnh tệp."});
if (I18N["hu"]) Object.assign(I18N["hu"], {"tk_kd_zones": "Egy találkozó saját időzónát is megtarthat, ha a dátumbeállításokban be van jelölve az <b>Időzónák megjelenítése</b>. Az időpontokat annak az időzónának az órája szerint kell megadni, és az időzóna nevével együtt tárolódnak, így egy tokiói 9:00-s megbeszélés ott 9:00 marad, amikor bármelyik hely átállítja az óráját.", "tk_kd_ics_more": "Az ismétlődések <b>RRULE</b>-ként mennek ki, a hónap első-negyedik vagy utolsó adott napjával együtt; a további dátumok <b>RDATE</b>-ként, a kihagyottak <b>EXDATE</b>-ként. Az időzónák <b>VTIMEZONE</b> definícióikkal együtt utaznak, és a fájl saját definíciója is beolvasásra kerül, ha a Windows nem ismeri a nevet. Egy már meglévő megbeszélés újabb meghívója (magasabb <b>SEQUENCE</b>) frissíti azt, a lemondás pedig eltávolítja, miután az importálás rákérdez.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> és <b>reminder_state</b> - a 30 napig megőrzött nemrég töröltek, a mentett sablonok, és hogy mely emlékeztetőket vetették el vagy halasztották el. A napi biztonsági mentések a fájl melletti <b>Backups</b> mappába kerülnek."});
if (I18N["es"]) Object.assign(I18N["es"], {"tk_kd_zones": "Una cita también puede tener su propia zona horaria, una vez marcada la opción <b>Mostrar zonas horarias</b> en la configuración de fechas. Sus horas se escriben con el reloj de esa zona y se guardan con su nombre, así que una reunión a las 9:00 en Tokio sigue a las 9:00 allí cuando cualquiera de los dos lugares cambia la hora.", "tk_kd_ics_more": "Las repeticiones salen como <b>RRULE</b>, incluidos del primer al cuarto o el último día de la semana del mes, con las fechas extra como <b>RDATE</b> y las omitidas como <b>EXDATE</b>. Las zonas horarias viajan con sus definiciones <b>VTIMEZONE</b>, y se lee la definición propia del archivo cuando Windows no conoce el nombre. Una invitación más reciente para una reunión que ya está aquí (un <b>SEQUENCE</b> mayor) la actualiza y una cancelación la quita, después de que la importación pregunte.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> y <b>reminder_state</b>: elementos eliminados recientemente durante 30 días, plantillas guardadas y qué recordatorios se descartaron o se pospusieron. Las copias de seguridad diarias van a una carpeta <b>Backups</b> junto al archivo."});
if (I18N["fr"]) Object.assign(I18N["fr"], {"tk_kd_zones": "Un rendez-vous peut aussi garder son propre fuseau horaire, une fois <b>Afficher les fuseaux horaires</b> coché dans les réglages de date. Ses heures sont saisies à l'heure de ce fuseau et enregistrées avec son nom : une réunion à 9:00 à Tokyo reste à 9:00 là-bas quand l'un ou l'autre lieu change d'heure.", "tk_kd_ics_more": "Les séries partent en <b>RRULE</b>, y compris du premier au quatrième ou le dernier jour de la semaine du mois, avec les dates supplémentaires en <b>RDATE</b> et les dates sautées en <b>EXDATE</b>. Les fuseaux horaires voyagent avec leurs définitions <b>VTIMEZONE</b>, et la définition propre au fichier est lue quand Windows ne connaît pas le nom. Une invitation plus récente pour une réunion déjà présente (un <b>SEQUENCE</b> plus élevé) la met à jour et une annulation la retire, après confirmation à l'importation.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> et <b>reminder_state</b> - les éléments supprimés récemment, gardés 30 jours, les modèles enregistrés, et les rappels ignorés ou reportés. Les sauvegardes quotidiennes vont dans un dossier <b>Backups</b> à côté du fichier."});
if (I18N["de"]) Object.assign(I18N["de"], {"tk_kd_zones": "Ein Termin kann auch eine eigene Zeitzone behalten, sobald in den Datumseinstellungen <b>Zeitzonen anzeigen</b> angehakt ist. Seine Zeiten werden in der Uhrzeit dieser Zone eingegeben und mit ihrem Namen gespeichert, sodass ein Termin um 9:00 in Tokio dort um 9:00 bleibt, wenn einer der beiden Orte die Uhr umstellt.", "tk_kd_ics_more": "Serien gehen als <b>RRULE</b> hinaus, einschließlich des ersten bis vierten oder letzten Wochentags eines Monats, mit zusätzlichen Terminen als <b>RDATE</b> und ausgelassenen als <b>EXDATE</b>. Zeitzonen reisen mit ihren <b>VTIMEZONE</b>-Definitionen, und die eigene Definition einer Datei wird gelesen, wenn Windows den Namen nicht kennt. Eine neuere Einladung für einen bereits vorhandenen Termin (eine höhere <b>SEQUENCE</b>) aktualisiert ihn, eine Absage entfernt ihn, nachdem der Import nachgefragt hat.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> und <b>reminder_state</b> - kürzlich Gelöschtes für 30 Tage, gespeicherte Vorlagen und welche Erinnerungen verworfen oder zurückgestellt wurden. Tägliche Sicherungen landen in einem Ordner <b>Backups</b> neben der Datei."});
if (I18N["cs"]) Object.assign(I18N["cs"], {"tk_kd_zones": "Schůzka si také může ponechat vlastní časové pásmo, jakmile je v nastavení data zaškrtnuto <b>Zobrazit časová pásma</b>. Její časy se zadávají podle hodin tohoto pásma a ukládají se s jeho názvem, takže schůzka v 9:00 v Tokiu tam zůstane v 9:00, když kterékoli z míst změní čas.", "tk_kd_ics_more": "Opakování se exportují jako <b>RRULE</b>, včetně prvního až čtvrtého nebo posledního dne v týdnu v měsíci, s dalšími daty jako <b>RDATE</b> a vynechanými jako <b>EXDATE</b>. Časová pásma putují se svými definicemi <b>VTIMEZONE</b> a vlastní definice souboru se načte, když Windows název nezná. Novější pozvánka na schůzku, která už tu je (vyšší <b>SEQUENCE</b>), ji aktualizuje a zrušení ji odstraní, poté co se import zeptá.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> a <b>reminder_state</b> - nedávno smazané položky po 30 dní, uložené šablony a která připomenutí byla zavřena nebo odložena. Denní zálohy se ukládají do složky <b>Backups</b> vedle souboru."});
if (I18N["tr"]) Object.assign(I18N["tr"], {"tk_kd_zones": "Bir randevu, tarih ayarlarında <b>Saat dilimlerini göster</b> işaretlendiğinde kendi saat dilimini de koruyabilir. Saatleri o dilimin saatine göre yazılır ve dilimin adıyla saklanır; böylece Tokyo'daki 9:00 toplantısı, iki yerden biri saatini değiştirdiğinde orada 9:00'da kalır.", "tk_kd_ics_more": "Yinelemeler <b>RRULE</b> olarak dışa aktarılır; ayın birinci ile dördüncü ya da son haftanın günü de dahil. Ek tarihler <b>RDATE</b>, atlananlar <b>EXDATE</b> olarak gider. Saat dilimleri <b>VTIMEZONE</b> tanımlarıyla taşınır ve Windows adı tanımadığında dosyanın kendi tanımı okunur. Burada zaten olan bir toplantı için daha yeni bir davet (daha yüksek <b>SEQUENCE</b>) onu günceller, iptal ise kaldırır; içe aktarma önce sorar.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> ve <b>reminder_state</b> - 30 gün tutulan son silinenler, kaydedilmiş şablonlar ve hangi anımsatıcıların kapatıldığı ya da ertelendiği. Günlük yedekler dosyanın yanındaki <b>Backups</b> klasörüne gider."});
if (I18N["ja"]) Object.assign(I18N["ja"], {"tk_kd_zones": "日付設定で <b>タイム ゾーンを表示</b> をオンにすると、予定ごとに独自のタイム ゾーンを持たせることもできます。時刻はそのゾーンの時計で入力され、ゾーン名とともに保存されるため、東京で 9:00 の会議は、どちらかの地域で時計が切り替わっても現地 9:00 のままです。", "tk_kd_ics_more": "繰り返しは <b>RRULE</b> として書き出され、月の第 1 から第 4 または最終の曜日にも対応します。追加の日は <b>RDATE</b>、スキップした日は <b>EXDATE</b> になります。タイム ゾーンは <b>VTIMEZONE</b> の定義とともに渡され、Windows が名前を知らない場合はファイル自身の定義を読み取ります。すでにある会議の新しい招待 (より大きい <b>SEQUENCE</b>) はそれを更新し、キャンセルは削除します。インポート時に確認があります。", "tk_kd_file_more": "<b>deleted</b>、<b>templates</b>、<b>reminder_state</b> - 30 日間保持される最近削除した項目、保存したテンプレート、閉じたり再通知したりしたリマインダー。毎日のバックアップはファイルと同じ場所の <b>Backups</b> フォルダーに保存されます。"});
if (I18N["pl"]) Object.assign(I18N["pl"], {"tk_kd_zones": "Spotkanie może też zachować własną strefę czasową, gdy w ustawieniach daty zaznaczono <b>Pokaż strefy czasowe</b>. Jego godziny wpisuje się według zegara tej strefy i zapisuje z jej nazwą, więc spotkanie o 9:00 w Tokio zostaje tam o 9:00, gdy któreś z miejsc zmienia czas.", "tk_kd_ics_more": "Cykle trafiają do pliku jako <b>RRULE</b>, także pierwszy do czwartego lub ostatni dzień tygodnia w miesiącu, dodatkowe daty jako <b>RDATE</b>, a pominięte jako <b>EXDATE</b>. Strefy czasowe wędrują ze swoimi definicjami <b>VTIMEZONE</b>, a własna definicja pliku jest odczytywana, gdy Windows nie zna nazwy. Nowsze zaproszenie na spotkanie, które już tu jest (wyższy <b>SEQUENCE</b>), aktualizuje je, a odwołanie usuwa, po pytaniu przy imporcie.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> i <b>reminder_state</b> - ostatnio usunięte przez 30 dni, zapisane szablony oraz które przypomnienia zamknięto lub odłożono. Codzienne kopie zapasowe trafiają do folderu <b>Backups</b> obok pliku."});
if (I18N["bn"]) Object.assign(I18N["bn"], {"tk_kd_zones": "তারিখ সেটিংসে <b>সময় অঞ্চল দেখান</b> চালু করলে একটি অ্যাপয়েন্টমেন্ট নিজস্ব সময় অঞ্চলও রাখতে পারে। এর সময় সেই অঞ্চলের ঘড়িতে লেখা হয় এবং অঞ্চলের নামসহ সংরক্ষিত হয়, তাই টোকিওতে 9:00-এর মিটিং দুই জায়গার যেকোনোটিতে ঘড়ি বদলালেও সেখানে 9:00-এই থাকে।", "tk_kd_ics_more": "পুনরাবৃত্তি <b>RRULE</b> হিসেবে যায়, মাসের প্রথম থেকে চতুর্থ বা শেষ সপ্তাহের দিনসহ; অতিরিক্ত তারিখ <b>RDATE</b> এবং বাদ দেওয়া তারিখ <b>EXDATE</b> হিসেবে। সময় অঞ্চল তাদের <b>VTIMEZONE</b> সংজ্ঞাসহ যায়, এবং Windows নামটি না চিনলে ফাইলের নিজস্ব সংজ্ঞা পড়া হয়। এখানে আগে থেকে থাকা মিটিংয়ের নতুন আমন্ত্রণ (বেশি <b>SEQUENCE</b>) সেটিকে হালনাগাদ করে এবং বাতিল করলে সরিয়ে দেয়, ইমপোর্ট জিজ্ঞেস করার পরে।", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> এবং <b>reminder_state</b> - ৩০ দিন রাখা সম্প্রতি মুছে ফেলা, সংরক্ষিত টেমপ্লেট, এবং কোন রিমাইন্ডার বন্ধ বা স্থগিত করা হয়েছে। প্রতিদিনের ব্যাকআপ ফাইলের পাশে <b>Backups</b> ফোল্ডারে যায়।"});
if (I18N["zh-CN"]) Object.assign(I18N["zh-CN"], {"tk_kd_zones": "在日期设置中勾选<b>显示时区</b>后，约会也可以保留自己的时区。其时间按该时区的时钟输入，并与时区名称一起保存，因此东京 9:00 的会议在任一地区调整时钟时，仍是当地 9:00。", "tk_kd_ics_more": "重复约会以 <b>RRULE</b> 导出，包括每月第一至第四个或最后一个星期几；额外日期为 <b>RDATE</b>，跳过的日期为 <b>EXDATE</b>。时区随其 <b>VTIMEZONE</b> 定义一起传递，Windows 不认识的名称会读取文件自带的定义。已有会议的较新邀请（更高的 <b>SEQUENCE</b>）会更新它，取消则会移除它，导入前会先询问。", "tk_kd_file_more": "<b>deleted</b>、<b>templates</b> 和 <b>reminder_state</b> - 保留 30 天的最近删除项、已保存的模板，以及哪些提醒已关闭或稍后提醒。每日备份保存在文件旁的 <b>Backups</b> 文件夹中。"});
if (I18N["zh-TW"]) Object.assign(I18N["zh-TW"], {"tk_kd_zones": "在日期設定中勾選<b>顯示時區</b>後，約會也可以保留自己的時區。其時間依該時區的時鐘輸入，並與時區名稱一起儲存，因此東京 9:00 的會議在任一地區調整時鐘時，仍是當地 9:00。", "tk_kd_ics_more": "重複約會以 <b>RRULE</b> 匯出，包括每月第一至第四個或最後一個星期幾；額外日期為 <b>RDATE</b>，略過的日期為 <b>EXDATE</b>。時區隨其 <b>VTIMEZONE</b> 定義一起傳遞，Windows 不認得的名稱會讀取檔案內的定義。已有會議的較新邀請（較高的 <b>SEQUENCE</b>）會更新它，取消則會移除它，匯入前會先詢問。", "tk_kd_file_more": "<b>deleted</b>、<b>templates</b> 和 <b>reminder_state</b> - 保留 30 天的最近刪除項目、已儲存的範本，以及哪些提醒已關閉或延後。每日備份儲存在檔案旁的 <b>Backups</b> 資料夾中。"});
if (I18N["it"]) Object.assign(I18N["it"], {"tk_kd_zones": "Un appuntamento può anche mantenere un proprio fuso orario, una volta spuntato <b>Mostra i fusi orari</b> nelle impostazioni della data. I suoi orari si scrivono con l'ora di quel fuso e si salvano con il suo nome, così una riunione alle 9:00 a Tokyo resta alle 9:00 lì quando uno dei due luoghi cambia l'ora.", "tk_kd_ics_more": "Le ricorrenze escono come <b>RRULE</b>, compresi dal primo al quarto o l'ultimo giorno della settimana del mese, con le date aggiuntive come <b>RDATE</b> e quelle saltate come <b>EXDATE</b>. I fusi orari viaggiano con le loro definizioni <b>VTIMEZONE</b>, e la definizione propria del file viene letta quando Windows non conosce il nome. Un invito più recente per una riunione già presente (un <b>SEQUENCE</b> più alto) la aggiorna e un annullamento la rimuove, dopo la domanda dell'importazione.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> e <b>reminder_state</b> - gli elementi eliminati di recente per 30 giorni, i modelli salvati e quali promemoria sono stati chiusi o posticipati. I backup giornalieri vanno in una cartella <b>Backups</b> accanto al file."});
if (I18N["ru"]) Object.assign(I18N["ru"], {"tk_kd_zones": "Встреча также может сохранять собственный часовой пояс, если в настройках даты отмечено <b>Показывать часовые пояса</b>. Её время вводится по часам этого пояса и хранится вместе с его названием, поэтому встреча в 9:00 в Токио остаётся там в 9:00, когда любое из мест переводит часы.", "tk_kd_ics_more": "Повторы выгружаются как <b>RRULE</b>, включая с первого по четвёртый или последний день недели месяца, дополнительные даты как <b>RDATE</b>, а пропущенные как <b>EXDATE</b>. Часовые пояса передаются вместе с определениями <b>VTIMEZONE</b>, а собственное определение файла читается, когда Windows не знает имени. Более новое приглашение на уже имеющуюся встречу (больший <b>SEQUENCE</b>) обновляет её, а отмена удаляет, после вопроса при импорте.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> и <b>reminder_state</b> - недавно удалённое на 30 дней, сохранённые шаблоны и какие напоминания закрыты или отложены. Ежедневные резервные копии попадают в папку <b>Backups</b> рядом с файлом."});
if (I18N["kk"]) Object.assign(I18N["kk"], {"tk_kd_zones": "Күн баптауларында <b>Уақыт белдеулерін көрсету</b> белгіленгенде, кездесу өз уақыт белдеуін де сақтай алады. Оның уақыты сол белдеудің сағатымен енгізіліп, белдеу атауымен бірге сақталады, сондықтан Токиодағы 9:00 кездесуі екі жердің бірі сағатын ауыстырса да сонда 9:00 болып қалады.", "tk_kd_ics_more": "Қайталанулар <b>RRULE</b> ретінде шығады, айдың бірінші-төртінші немесе соңғы апта күнін қоса; қосымша күндер <b>RDATE</b>, өткізілгендер <b>EXDATE</b> ретінде. Уақыт белдеулері <b>VTIMEZONE</b> анықтамаларымен бірге беріледі, ал Windows атауды білмесе, файлдың өз анықтамасы оқылады. Мұнда бар кездесудің жаңарақ шақыруы (жоғарырақ <b>SEQUENCE</b>) оны жаңартады, ал бас тарту оны жояды, импорт сұрағаннан кейін.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> және <b>reminder_state</b> - 30 күн сақталатын жақында жойылғандар, сақталған үлгілер және қай еске салғыштар жабылғаны не кейінге қалдырылғаны. Күнделікті сақтық көшірмелер файлдың жанындағы <b>Backups</b> қалтасына түседі."});
if (I18N["uk"]) Object.assign(I18N["uk"], {"tk_kd_zones": "Зустріч також може зберігати власний часовий пояс, якщо в налаштуваннях дати позначено <b>Показувати часові пояси</b>. Її час вводиться за годинником цього поясу й зберігається з його назвою, тож зустріч о 9:00 у Токіо лишається там о 9:00, коли будь-яке з місць переводить годинник.", "tk_kd_ics_more": "Повтори вивантажуються як <b>RRULE</b>, зокрема з першого по четвертий або останній день тижня місяця, додаткові дати як <b>RDATE</b>, а пропущені як <b>EXDATE</b>. Часові пояси передаються разом із визначеннями <b>VTIMEZONE</b>, а власне визначення файлу читається, коли Windows не знає назви. Новіше запрошення на зустріч, що вже є (більший <b>SEQUENCE</b>), оновлює її, а скасування вилучає, після запитання під час імпорту.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> і <b>reminder_state</b> - нещодавно видалене протягом 30 днів, збережені шаблони та які нагадування закрито чи відкладено. Щоденні резервні копії потрапляють до теки <b>Backups</b> поруч із файлом."});
if (I18N["nb"]) Object.assign(I18N["nb"], {"tk_kd_zones": "En avtale kan også beholde sin egen tidssone når <b>Vis tidssoner</b> er krysset av i datoinnstillingene. Tidene skrives inn etter klokken i den sonen og lagres med navnet, så et møte kl. 9:00 i Tokyo blir værende kl. 9:00 der når ett av stedene stiller klokken.", "tk_kd_ics_more": "Gjentakelser går ut som <b>RRULE</b>, også første til fjerde eller siste ukedag i måneden, med ekstra datoer som <b>RDATE</b> og hoppede datoer som <b>EXDATE</b>. Tidssoner følger med sine <b>VTIMEZONE</b>-definisjoner, og filens egen definisjon leses når Windows ikke kjenner navnet. En nyere invitasjon til et møte som allerede er her (høyere <b>SEQUENCE</b>), oppdaterer det, og en avlysning fjerner det, etter at importen har spurt.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> og <b>reminder_state</b> - nylig slettet i 30 dager, lagrede maler og hvilke påminnelser som er avvist eller utsatt. Daglige sikkerhetskopier legges i en <b>Backups</b>-mappe ved siden av filen."});
if (I18N["pt"]) Object.assign(I18N["pt"], {"tk_kd_zones": "Um compromisso também pode manter o próprio fuso horário, depois de marcar <b>Mostrar fusos horários</b> nas configurações de data. Os horários são digitados no relógio desse fuso e salvos com o nome dele, então uma reunião às 9:00 em Tóquio continua às 9:00 lá quando qualquer um dos lugares muda o relógio.", "tk_kd_ics_more": "As repetições saem como <b>RRULE</b>, incluindo do primeiro ao quarto ou o último dia da semana do mês, com datas extras como <b>RDATE</b> e as puladas como <b>EXDATE</b>. Os fusos horários vão com suas definições <b>VTIMEZONE</b>, e a definição própria do arquivo é lida quando o Windows não conhece o nome. Um convite mais novo para uma reunião que já está aqui (um <b>SEQUENCE</b> maior) a atualiza e um cancelamento a remove, depois que a importação pergunta.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> e <b>reminder_state</b> - itens excluídos recentemente por 30 dias, modelos salvos e quais lembretes foram dispensados ou adiados. Os backups diários vão para uma pasta <b>Backups</b> ao lado do arquivo."});
if (I18N["sl"]) Object.assign(I18N["sl"], {"tk_kd_zones": "Sestanek lahko ohrani tudi svoj časovni pas, ko je v nastavitvah datuma označeno <b>Prikaži časovne pasove</b>. Njegove ure se vnašajo po uri tega pasu in shranijo z njegovim imenom, zato sestanek ob 9:00 v Tokiu tam ostane ob 9:00, ko katerikoli od krajev prestavi uro.", "tk_kd_ics_more": "Ponavljanja gredo ven kot <b>RRULE</b>, tudi prvi do četrti ali zadnji dan v tednu v mesecu, dodatni datumi kot <b>RDATE</b> in izpuščeni kot <b>EXDATE</b>. Časovni pasovi potujejo s svojimi definicijami <b>VTIMEZONE</b>, lastna definicija datoteke pa se prebere, ko Windows imena ne pozna. Novejše vabilo na sestanek, ki je že tu (višji <b>SEQUENCE</b>), ga posodobi, preklic pa ga odstrani, potem ko uvoz vpraša.", "tk_kd_file_more": "<b>deleted</b>, <b>templates</b> in <b>reminder_state</b> - nedavno izbrisano za 30 dni, shranjene predloge in kateri opomniki so bili zaprti ali odloženi. Dnevne varnostne kopije gredo v mapo <b>Backups</b> poleg datoteke."});
